void OS::_set_logger(CompositeLogger* p_logger)
{
	if (_logger) {
		memdelete(_logger);
	}
	_logger = p_logger;
}

void OS::add_logger(Logger* p_logger)
{
	if (!_logger) {
		Vector<Logger*> loggers;
		loggers.push_back(p_logger);
		_logger = memnew(CompositeLogger(loggers));
	}
	else {
		_logger->add_logger(p_logger);
	}
}

