#ifdef DEBUG_ENABLED
#define CHULL_ASSERT(m_cond) \
	if constexpr (true) { \
		if (unlikely(!(m_cond))) { \
			ERR_PRINT("Assertion \"" _STR(m_cond) "\" failed."); \
		} \
	} else \
		((void)0)
#else
#define CHULL_ASSERT(m_cond) \
	if constexpr (true) { \
	} else \
		((void)0)
#endif

