#include <cstdio>
#include "core/version_generated.gen.h" // For regex.

#ifdef MODULE_REGEX_ENABLED
#endif // MODULE_REGEX_ENABLED

#if defined(MINGW_ENABLED) || defined(_MSC_VER)
#define sprintf sprintf_s
#endif

bool Logger::should_log(bool p_err)
{
	return (!p_err || CoreGlobals::print_error_enabled) &&
		   (p_err || CoreGlobals::print_line_enabled);
}

void Logger::set_flush_stdout_on_print(bool p_value) { _flush_stdout_on_print = p_value; }

void Logger::logf(const char* p_format, ...)
{
	if (!should_log(false)) {
		return;
	}

	va_list argp;
	va_start(argp, p_format);

	logv(p_format, argp, false);

	va_end(argp);
}

void Logger::logf_error(const char* p_format, ...)
{
	if (!should_log(true)) {
		return;
	}

	va_list argp;
	va_start(argp, p_format);

	logv(p_format, argp, true);

	va_end(argp);
}

void RotatedFileLogger::clear_old_backups()
{
	int max_backups = max_files - 1; // -1 for the current file

	String basename = base_path.get_file().get_basename();
	String extension = base_path.get_extension();

	Ref<DirAccess> da = DirAccess::open(base_path.get_base_dir());
	if (da.is_null()) {
		return;
	}

	da->list_dir_begin();
	String f = da->get_next();
	// backups is a RBSet because it guarantees that iterating on it is done in sorted order.
	// RotatedFileLogger depends on this behavior to delete the oldest log file first.
	RBSet<String> backups;
	while (!f.is_empty()) {
		if (!da->current_is_dir() && f.begins_with(basename) && f.get_extension() == extension &&
			f != base_path.get_file()) {
			backups.insert(f);
		}
		f = da->get_next();
	}
	da->list_dir_end();

	if (backups.size() > max_backups) {
		// since backups are appended with timestamp and Set iterates them in sorted order,
		// first backups are the oldest
		int to_delete = backups.size() - max_backups;
		for (RBSet<String>::Element* E = backups.front(); E && to_delete > 0;
			 E = E->next(), --to_delete) {
			da->remove(E->get());
		}
	}
}

void RotatedFileLogger::rotate_file()
{
	file.unref();

	if (FileAccess::exists(base_path)) {
		if (max_files > 1) {
			String timestamp =
				Time::get_datetime_string_from_system().replace_char(':', '.');
			String backup_name = base_path.get_basename() + timestamp;
			if (!base_path.get_extension().is_empty()) {
				backup_name += "." + base_path.get_extension();
			}

			Ref<DirAccess> da = DirAccess::open(base_path.get_base_dir());
			if (da.is_valid()) {
				da->copy(base_path, backup_name);
			}
			clear_old_backups();
		}
	}
	else {
		Ref<DirAccess> da = DirAccess::create(DirAccess::ACCESS_USERDATA);
		if (da.is_valid()) {
			da->make_dir_recursive(base_path.get_base_dir());
		}
	}

	file = FileAccess::open(base_path, FileAccess::WRITE);
}

RotatedFileLogger::RotatedFileLogger(const String& p_base_path, int p_max_files)
	: base_path(p_base_path.simplify_path()), max_files(p_max_files > 0 ? p_max_files : 1)
{
	rotate_file();

#ifdef MODULE_REGEX_ENABLED
	strip_ansi_regex.instantiate();
	strip_ansi_regex->compile("\u001b\\[((?:\\d|;)*)([a-zA-Z])");
#endif // MODULE_REGEX_ENABLED
}

void RotatedFileLogger::logv(const char* p_format, va_list p_list, bool p_err)
{
	if (!should_log(p_err)) {
		return;
	}

	if (file.is_valid()) {
		const int static_buf_size = 512;
		char static_buf[static_buf_size];
		char* buf = static_buf;
		va_list list_copy;
		va_copy(list_copy, p_list);
		int len = vsnprintf(buf, static_buf_size, p_format, p_list);
		if (len >= static_buf_size) {
			buf = (char*)Memory::alloc_static(len + 1);
			vsnprintf(buf, len + 1, p_format, list_copy);
		}
		va_end(list_copy);

#ifdef MODULE_REGEX_ENABLED
		// Strip ANSI escape codes (such as those inserted by `print_rich()`)
		// before writing to file, as text editors cannot display those
		// correctly.
		file->store_string(strip_ansi_regex->sub(String::utf8(buf), "", true));
#else
		file->store_buffer((uint8_t*)buf, len);
#endif // MODULE_REGEX_ENABLED

		if (len >= static_buf_size) {
			Memory::free_static(buf);
		}

		if (p_err || _flush_stdout_on_print) {
			// Don't always flush when printing stdout to avoid performance
			// issues when `print()` is spammed in release builds.
			file->flush();
		}
	}
}

#if defined(UNIX_ENABLED)
#include <syslog.h>
#endif
#if defined(ANDROID_ENABLED)
#include <android/log.h>
#endif
#if defined(__APPLE__)
#include <os/log.h>
Logger::Logger(const char* p_subsystem) :
	backend(BACKEND_OS_LOG),
	os_log_handle((void*)os_log_create(p_subsystem ? p_subsystem : "org.voltaire.engine", "engine"))
{
}
#endif

void Logger::logv(const char* p_format, va_list p_list, bool p_err)
{
	if (!should_log(p_err)) {
		return;
	}

#if defined(UNIX_ENABLED)
	if (backend == BACKEND_SYSLOG) {
		vsyslog(p_err ? LOG_ERR : LOG_INFO, p_format, p_list);
		return;
	}
#endif
#if defined(ANDROID_ENABLED)
	if (backend == BACKEND_ANDROID) {
		__android_log_vprint(p_err ? ANDROID_LOG_ERROR : ANDROID_LOG_INFO, "voltaire", p_format, p_list);
		return;
	}
#endif
#if defined(__APPLE__)
	if (backend == BACKEND_OS_LOG) {
		char static_buf[1024];
		char* buf = static_buf;
		va_list list_copy;
		va_copy(list_copy, p_list);
		int len = vsnprintf(buf, sizeof(static_buf), p_format, p_list);
		if (len >= (int)sizeof(static_buf)) {
			buf = (char*)Memory::alloc_static(len + 1);
			vsnprintf(buf, len + 1, p_format, list_copy);
		}
		va_end(list_copy);
		os_log_with_type((os_log_t)os_log_handle, p_err ? OS_LOG_TYPE_ERROR : OS_LOG_TYPE_INFO, "%{public}s", buf);
		if (len >= (int)sizeof(static_buf)) {
			Memory::free_static(buf);
		}
		return;
	}
#endif
#if defined(WINDOWS_ENABLED)
	if (backend == BACKEND_WINDOWS_TERMINAL) {
		const unsigned int BUFFER_SIZE = 16384;
		char buf[BUFFER_SIZE + 1];
		int len = vsnprintf(buf, BUFFER_SIZE, p_format, p_list);
		if (len > 0) {
			fflush(stdout);
			DWORD written = 0;
			HANDLE h = p_err ? GetStdHandle(STD_ERROR_HANDLE) : GetStdHandle(STD_OUTPUT_HANDLE);
			WriteFile(h, buf, MIN((unsigned int)len, BUFFER_SIZE), &written, nullptr);
#ifdef DEBUG_ENABLED
			FlushFileBuffers(h);
#endif
		}
		return;
	}
#endif

	if (p_err) {
		vfprintf(stderr, p_format, p_list);
	}
	else {
		vprintf(p_format, p_list);
		if (_flush_stdout_on_print) {
			fflush(stdout);
		}
	}
}

CompositeLogger::CompositeLogger(const Vector<Logger*>& p_loggers) : loggers(p_loggers) {}

void CompositeLogger::logv(const char* p_format, va_list p_list, bool p_err)
{
	if (!should_log(p_err)) {
		return;
	}

	for (int i = 0; i < loggers.size(); ++i) {
		va_list list_copy;
		va_copy(list_copy, p_list);
		loggers[i]->logv(p_format, list_copy, p_err);
		va_end(list_copy);
	}
}

void CompositeLogger::add_logger(Logger* p_logger) { loggers.push_back(p_logger); }

CompositeLogger::~CompositeLogger()
{
	for (int i = 0; i < loggers.size(); ++i) {
		memdelete(loggers[i]);
	}
}
