int Performance::_get_orphan_node_count()
{
#ifdef DEBUG_ENABLED
	const int total_node_count = Node::total_node_count.get();
	const int orphan_node_count = total_node_count - _get_node_count();
	return orphan_node_count;
#else
	return 0;
#endif
}

