static VkPipelineStageFlags _rd_to_vk_pipeline_stages(uint32_t p_stages)
{
	VkPipelineStageFlags vk_flags = 0;
	if (Utils::has_flag(p_stages, RDD::PIPELINE_STAGE_COPY_BIT) ||
		Utils::has_flag(p_stages, RDD::PIPELINE_STAGE_RESOLVE_BIT)) {
		// Transfer has been split into copy and resolve bits. Clear them and merge them into one
		// bit.
		vk_flags = Utils::set_flag(vk_flags, VK_PIPELINE_STAGE_TRANSFER_BIT);
		p_stages = Utils::clear_flag(p_stages, RDD::PIPELINE_STAGE_COPY_BIT);
		p_stages = Utils::clear_flag(p_stages, RDD::PIPELINE_STAGE_RESOLVE_BIT);
	}

	if (Utils::has_flag(p_stages, RDD::PIPELINE_STAGE_CLEAR_STORAGE_BIT)) {
		// Vulkan should never use this as API_TRAIT_CLEAR_RESOURCES_WITH_VIEWS is not specified.
		// Therefore, storage is never cleared with an explicit command.
		p_stages = Utils::clear_flag(p_stages, RDD::PIPELINE_STAGE_CLEAR_STORAGE_BIT);
	}

	// The rest of the flags have compatible numeric values with Vulkan.
	return VkPipelineStageFlags(int64_t(p_stages)) | vk_flags;
}

static VkAccessFlags _rd_to_vk_access_flags(uint32_t p_access)
{
	VkAccessFlags vk_flags = 0;
	if (Utils::has_flag(p_access, RDD::BARRIER_ACCESS_COPY_READ_BIT) ||
		Utils::has_flag(p_access, RDD::BARRIER_ACCESS_RESOLVE_READ_BIT)) {
		vk_flags = Utils::set_flag(vk_flags, VK_ACCESS_TRANSFER_READ_BIT);
		p_access = Utils::clear_flag(p_access, RDD::BARRIER_ACCESS_COPY_READ_BIT);
		p_access = Utils::clear_flag(p_access, RDD::BARRIER_ACCESS_RESOLVE_READ_BIT);
	}

	if (Utils::has_flag(p_access, RDD::BARRIER_ACCESS_COPY_WRITE_BIT) ||
		Utils::has_flag(p_access, RDD::BARRIER_ACCESS_RESOLVE_WRITE_BIT)) {
		vk_flags = Utils::set_flag(vk_flags, VK_ACCESS_TRANSFER_WRITE_BIT);
		p_access = Utils::clear_flag(p_access, RDD::BARRIER_ACCESS_COPY_WRITE_BIT);
		p_access = Utils::clear_flag(p_access, RDD::BARRIER_ACCESS_RESOLVE_WRITE_BIT);
	}

	if (Utils::has_flag(p_access, RDD::BARRIER_ACCESS_STORAGE_CLEAR_BIT)) {
		// Vulkan should never use this as API_TRAIT_CLEAR_RESOURCES_WITH_VIEWS is not specified.
		// Therefore, storage is never cleared with an explicit command.
		p_access = Utils::clear_flag(p_access, RDD::BARRIER_ACCESS_STORAGE_CLEAR_BIT);
	}

	// The rest of the flags have compatible numeric values with Vulkan.
	return VkAccessFlags(int64_t(p_access)) | vk_flags;
}

// RDD::CompareOperator == VkCompareOp.
static_assert(ENUM_MEMBERS_EQUAL(RDC::COMPARE_OP_NEVER, VK_COMPARE_OP_NEVER));
static_assert(ENUM_MEMBERS_EQUAL(RDC::COMPARE_OP_LESS, VK_COMPARE_OP_LESS));
static_assert(ENUM_MEMBERS_EQUAL(RDC::COMPARE_OP_EQUAL, VK_COMPARE_OP_EQUAL));
static_assert(ENUM_MEMBERS_EQUAL(RDC::COMPARE_OP_LESS_OR_EQUAL, VK_COMPARE_OP_LESS_OR_EQUAL));
static_assert(ENUM_MEMBERS_EQUAL(RDC::COMPARE_OP_GREATER, VK_COMPARE_OP_GREATER));
static_assert(ENUM_MEMBERS_EQUAL(RDC::COMPARE_OP_NOT_EQUAL, VK_COMPARE_OP_NOT_EQUAL));
static_assert(ENUM_MEMBERS_EQUAL(RDC::COMPARE_OP_GREATER_OR_EQUAL, VK_COMPARE_OP_GREATER_OR_EQUAL));
static_assert(ENUM_MEMBERS_EQUAL(RDC::COMPARE_OP_ALWAYS, VK_COMPARE_OP_ALWAYS));

static_assert(ARRAYS_COMPATIBLE_FIELDWISE(Rect2i, VkRect2D));

uint32_t RenderingDeviceDriverVulkan::SubgroupCapabilities::supported_stages_flags_rd() const
{
	uint32_t flags = 0;

	if (supported_stages & VK_SHADER_STAGE_VERTEX_BIT) {
		flags += RDC::SHADER_STAGE_VERTEX_BIT;
	}
	if (supported_stages & VK_SHADER_STAGE_TESSELLATION_CONTROL_BIT) {
		flags += RDC::SHADER_STAGE_TESSELATION_CONTROL_BIT;
	}
	if (supported_stages & VK_SHADER_STAGE_TESSELLATION_EVALUATION_BIT) {
		flags += RDC::SHADER_STAGE_TESSELATION_EVALUATION_BIT;
	}
	if (supported_stages & VK_SHADER_STAGE_GEOMETRY_BIT) {
		// FIXME: Add shader stage geometry bit.
	}
	if (supported_stages & VK_SHADER_STAGE_FRAGMENT_BIT) {
		flags += RDC::SHADER_STAGE_FRAGMENT_BIT;
	}
	if (supported_stages & VK_SHADER_STAGE_COMPUTE_BIT) {
		flags += RDC::SHADER_STAGE_COMPUTE_BIT;
	}
	if (supported_stages & VK_SHADER_STAGE_RAYGEN_BIT_KHR) {
		flags += RDC::SHADER_STAGE_RAYGEN_BIT;
	}
	if (supported_stages & VK_SHADER_STAGE_ANY_HIT_BIT_KHR) {
		flags += RDC::SHADER_STAGE_ANY_HIT_BIT;
	}
	if (supported_stages & VK_SHADER_STAGE_CLOSEST_HIT_BIT_KHR) {
		flags += RDC::SHADER_STAGE_CLOSEST_HIT_BIT;
	}
	if (supported_stages & VK_SHADER_STAGE_MISS_BIT_KHR) {
		flags += RDC::SHADER_STAGE_MISS_BIT;
	}
	if (supported_stages & VK_SHADER_STAGE_INTERSECTION_BIT_KHR) {
		flags += RDC::SHADER_STAGE_INTERSECTION_BIT;
	}

	return flags;
}

String RenderingDeviceDriverVulkan::SubgroupCapabilities::supported_stages_desc() const
{
	String res;

	if (supported_stages & VK_SHADER_STAGE_VERTEX_BIT) {
		res += ", STAGE_VERTEX";
	}
	if (supported_stages & VK_SHADER_STAGE_TESSELLATION_CONTROL_BIT) {
		res += ", STAGE_TESSELLATION_CONTROL";
	}
	if (supported_stages & VK_SHADER_STAGE_TESSELLATION_EVALUATION_BIT) {
		res += ", STAGE_TESSELLATION_EVALUATION";
	}
	if (supported_stages & VK_SHADER_STAGE_GEOMETRY_BIT) {
		res += ", STAGE_GEOMETRY";
	}
	if (supported_stages & VK_SHADER_STAGE_FRAGMENT_BIT) {
		res += ", STAGE_FRAGMENT";
	}
	if (supported_stages & VK_SHADER_STAGE_COMPUTE_BIT) {
		res += ", STAGE_COMPUTE";
	}

	// These are not defined on Android GRMBL.
	if (supported_stages & 0x00000100 /* VK_SHADER_STAGE_RAYGEN_BIT_KHR */) {
		res += ", STAGE_RAYGEN_KHR";
	}
	if (supported_stages & 0x00000200 /* VK_SHADER_STAGE_ANY_HIT_BIT_KHR */) {
		res += ", STAGE_ANY_HIT_KHR";
	}
	if (supported_stages & 0x00000400 /* VK_SHADER_STAGE_CLOSEST_HIT_BIT_KHR */) {
		res += ", STAGE_CLOSEST_HIT_KHR";
	}
	if (supported_stages & 0x00000800 /* VK_SHADER_STAGE_MISS_BIT_KHR */) {
		res += ", STAGE_MISS_KHR";
	}
	if (supported_stages & 0x00001000 /* VK_SHADER_STAGE_INTERSECTION_BIT_KHR */) {
		res += ", STAGE_INTERSECTION_KHR";
	}
	if (supported_stages & 0x00002000 /* VK_SHADER_STAGE_CALLABLE_BIT_KHR */) {
		res += ", STAGE_CALLABLE_KHR";
	}
	if (supported_stages & 0x00000040 /* VK_SHADER_STAGE_TASK_BIT_NV */) {
		res += ", STAGE_TASK_NV";
	}
	if (supported_stages & 0x00000080 /* VK_SHADER_STAGE_MESH_BIT_NV */) {
		res += ", STAGE_MESH_NV";
	}

	return res.substr(2); // Remove first ", ".
}

