void RenderingDeviceDriverVulkan::_register_requested_device_extension(
	const CharString& p_extension_name, bool p_required)
{
	ERR_FAIL_COND(requested_device_extensions.has(p_extension_name));
	requested_device_extensions[p_extension_name] = p_required;
}

Error RenderingDeviceDriverVulkan::_initialize_device_extensions()
{
	enabled_device_extension_names.clear();

	_register_requested_device_extension(VK_KHR_SWAPCHAIN_EXTENSION_NAME, true);
	_register_requested_device_extension(VK_KHR_MULTIVIEW_EXTENSION_NAME, false);
	_register_requested_device_extension(VK_KHR_FRAGMENT_SHADING_RATE_EXTENSION_NAME, false);
	_register_requested_device_extension(VK_EXT_FRAGMENT_DENSITY_MAP_EXTENSION_NAME, false);
	_register_requested_device_extension(VK_EXT_FRAGMENT_DENSITY_MAP_2_EXTENSION_NAME, false);
	_register_requested_device_extension(VK_QCOM_FRAGMENT_DENSITY_MAP_OFFSET_EXTENSION_NAME, false);
	_register_requested_device_extension(VK_KHR_CREATE_RENDERPASS_2_EXTENSION_NAME, false);
	_register_requested_device_extension(VK_KHR_SHADER_FLOAT16_INT8_EXTENSION_NAME, false);
	_register_requested_device_extension(VK_KHR_STORAGE_BUFFER_STORAGE_CLASS_EXTENSION_NAME, false);
	_register_requested_device_extension(VK_KHR_16BIT_STORAGE_EXTENSION_NAME, false);
	_register_requested_device_extension(VK_KHR_IMAGE_FORMAT_LIST_EXTENSION_NAME, false);
	_register_requested_device_extension(VK_KHR_MAINTENANCE_2_EXTENSION_NAME, false);
	_register_requested_device_extension(
		VK_EXT_PIPELINE_CREATION_CACHE_CONTROL_EXTENSION_NAME, false);
	_register_requested_device_extension(VK_EXT_SUBGROUP_SIZE_CONTROL_EXTENSION_NAME, false);
	_register_requested_device_extension(VK_EXT_ASTC_DECODE_MODE_EXTENSION_NAME, false);
	_register_requested_device_extension(VK_KHR_BUFFER_DEVICE_ADDRESS_EXTENSION_NAME, false);
	_register_requested_device_extension(VK_KHR_VULKAN_MEMORY_MODEL_EXTENSION_NAME, false);
	_register_requested_device_extension(VK_EXT_TEXTURE_COMPRESSION_ASTC_HDR_EXTENSION_NAME, false);
	_register_requested_device_extension(VK_KHR_DEPTH_STENCIL_RESOLVE_EXTENSION_NAME, false);
	_register_requested_device_extension(VK_KHR_ACCELERATION_STRUCTURE_EXTENSION_NAME, false);
	_register_requested_device_extension(VK_KHR_DEFERRED_HOST_OPERATIONS_EXTENSION_NAME, false);
	_register_requested_device_extension(VK_KHR_RAY_TRACING_PIPELINE_EXTENSION_NAME, false);
	_register_requested_device_extension(VK_NV_RAY_TRACING_VALIDATION_EXTENSION_NAME, false);
	_register_requested_device_extension(VK_KHR_SYNCHRONIZATION_2_EXTENSION_NAME, false);

	// We don't actually use this extension, but some runtime components on some platforms
	// can and will fill the validation layers with useless info otherwise if not enabled.
	_register_requested_device_extension(VK_KHR_EXTERNAL_MEMORY_FD_EXTENSION_NAME, false);

	if (Engine::is_generate_spirv_debug_info_enabled()) {
		_register_requested_device_extension(VK_KHR_SHADER_NON_SEMANTIC_INFO_EXTENSION_NAME, true);
	}

#if defined(VK_TRACK_DEVICE_MEMORY)
	if (Engine::is_extra_gpu_memory_tracking_enabled()) {
		_register_requested_device_extension(VK_EXT_DEVICE_MEMORY_REPORT_EXTENSION_NAME, false);
	}
#endif
	_register_requested_device_extension(VK_EXT_DEVICE_FAULT_EXTENSION_NAME, false);

	{
		// Debug marker extensions.
		// Should be last element in the array.
#ifdef DEV_ENABLED
		bool want_debug_markers = true;
#else
		bool want_debug_markers = OS::is_stdout_verbose();
#endif
		if (want_debug_markers) {
			_register_requested_device_extension(VK_EXT_DEBUG_MARKER_EXTENSION_NAME, false);
		}
	}

	_register_requested_device_extension(VK_KHR_DRIVER_PROPERTIES_EXTENSION_NAME, false);

	uint32_t device_extension_count = 0;
	VkResult err = vkEnumerateDeviceExtensionProperties(
		physical_device, nullptr, &device_extension_count, nullptr);
	ERR_FAIL_COND_V_MSG(err != VK_SUCCESS, ERR_CANT_CREATE,
		vformat("Couldn't get Vulkan device extension count (VkResult error %d).", err));
	ERR_FAIL_COND_V_MSG(device_extension_count == 0, ERR_CANT_CREATE,
		"Couldn't find any Vulkan device extensions. Do you have a compatible Vulkan installable "
		"client driver (ICD) installed?");

	TightLocalVector<VkExtensionProperties> device_extensions;
	device_extensions.resize(device_extension_count);
	err = vkEnumerateDeviceExtensionProperties(
		physical_device, nullptr, &device_extension_count, device_extensions.ptr());
	ERR_FAIL_COND_V_MSG(err != VK_SUCCESS, ERR_CANT_CREATE,
		vformat("Couldn't get Vulkan device extension properties (VkResult error %d).", err));

#if defined(SWAPPY_FRAME_PACING_ENABLED)
	if (swappy_frame_pacer_enable) {
		char** swappy_required_extensions;
		uint32_t swappy_required_extensions_count = 0;
		// Determine number of extensions required by Swappy frame pacer.
		SwappyVk_determineDeviceExtensions(physical_device, device_extension_count,
			device_extensions.ptr(), &swappy_required_extensions_count, nullptr);

		if (swappy_required_extensions_count < device_extension_count) {
			// Determine the actual extensions.
			swappy_required_extensions =
				(char**)malloc(swappy_required_extensions_count * sizeof(char*));
			char* pRequiredExtensionsData =
				(char*)malloc(swappy_required_extensions_count * (VK_MAX_EXTENSION_NAME_SIZE + 1));
			for (uint32_t i = 0; i < swappy_required_extensions_count; i++) {
				swappy_required_extensions[i] =
					&pRequiredExtensionsData[i * (VK_MAX_EXTENSION_NAME_SIZE + 1)];
			}
			SwappyVk_determineDeviceExtensions(physical_device, device_extension_count,
				device_extensions.ptr(), &swappy_required_extensions_count,
				swappy_required_extensions);

			// Enable extensions requested by Swappy.
			for (uint32_t i = 0; i < swappy_required_extensions_count; i++) {
				CharString extension_name(swappy_required_extensions[i]);
				if (requested_device_extensions.has(extension_name)) {
					enabled_device_extension_names.insert(extension_name);
				}
			}

			free(pRequiredExtensionsData);
			free(swappy_required_extensions);
		}
	}
#endif

#ifdef DEV_ENABLED
	for (uint32_t i = 0; i < device_extension_count; i++) {
		print_verbose(String("Vulkan: Found device extension ") +
					  String::utf8(device_extensions[i].extensionName));
	}
#endif

	// Enable all extensions that are supported and requested.
	for (uint32_t i = 0; i < device_extension_count; i++) {
		CharString extension_name(device_extensions[i].extensionName);
		if (requested_device_extensions.has(extension_name)) {
			enabled_device_extension_names.insert(extension_name);
		}
	}

	// Now check our requested extensions.
	for (KeyValue<CharString, bool>& requested_extension : requested_device_extensions) {
		if (!enabled_device_extension_names.has(requested_extension.key)) {
			if (requested_extension.value) {
				ERR_FAIL_V_MSG(ERR_BUG, String("Required Vulkan device extension ") +
											String::utf8(requested_extension.key) +
											String(" not found."));
			}
			else {
				print_verbose(String("Optional Vulkan device extension ") +
							  String::utf8(requested_extension.key) + String(" not found"));
			}
		}
	}

	return OK;
}

void RenderingDeviceDriverVulkan::_check_driver_workarounds(
	const VkPhysicalDeviceProperties& p_device_properties,
	const VkPhysicalDeviceDriverPropertiesKHR* p_driver_properties)
{
	// Workaround a driver bug on Adreno 5XX GPUs that causes a crash when
	// there are empty descriptor set layouts placed between non-empty ones.
	adreno_5xx_empty_descriptor_set_layout_workaround =
		p_device_properties.vendorID == RenderingContextDriver::Vendor::VENDOR_QUALCOMM &&
		p_device_properties.deviceID >= 0x5000000 && p_device_properties.deviceID < 0x6000000;

	// Workaround for the Adreno 6XX family of devices.
	//
	// There's a known issue with the Vulkan driver in this family of devices where it'll crash if a
	// dynamic state for drawing is used in a command buffer before a dispatch call is issued. As
	// both dynamic scissor and viewport are basic requirements for the engine to not bake this
	// state into the PSO, the only known way to fix this issue is to reset the command buffer
	// entirely.
	//
	// As the render graph has no built in limitations of whether it'll issue compute work before
	// anything needs to draw on the frame, and there's no guarantee that compute work will never be
	// dependent on rasterization in the future, this workaround will end recording on the current
	// command buffer any time a compute list is encountered after a draw list was executed. A new
	// command buffer will be created afterwards and the appropriate synchronization primitives will
	// be inserted.
	//
	// Executing this workaround has the added cost of synchronization between all the command
	// buffers that are created as well as all the individual submissions. This performance hit is
	// accepted for the sake of being able to support these devices without limiting the design of
	// the renderer.
	//
	// This bug was fixed in driver version 512.503.0, so we only enabled it on devices older than
	// this.
	//
	driver_workarounds.avoid_compute_after_draw =
		p_device_properties.vendorID == RenderingContextDriver::Vendor::VENDOR_QUALCOMM &&
		p_device_properties.deviceID >= 0x6000000 && // Adreno 6xx
		p_device_properties.driverVersion < VK_MAKE_VERSION(512, 503, 0) &&
		strstr(p_device_properties.deviceName, "Turnip") == nullptr;

	// Don't print pipeline compilation errors on Adreno 660, as they are expected to happen on this
	// device with ubershaders. Unhandled error cases will still pop up elsewhere in RD. (eg. when
	// attempting to bind an invalid pipeline.)
	driver_workarounds.dont_print_on_render_pipeline_creation_failure =
		p_device_properties.vendorID == RenderingContextDriver::Vendor::VENDOR_QUALCOMM &&
		p_device_properties.deviceID == 0x6060001 && // Adreno 660
		strstr(p_device_properties.deviceName, "Turnip") == nullptr;

	// Workaround a driver bug on Adreno 730 GPUs that keeps leaking memory on each call to
	// vkResetDescriptorPool. Which eventually run out of memory. In such case we should not be
	// using linear allocated pools Bug introduced in driver 512.597.0 and fixed in 512.671.0.
	// Confirmed by Qualcomm.
	if (linear_descriptor_pools_enabled) {
		const uint32_t reset_descriptor_pool_broken_driver_begin = VK_MAKE_VERSION(512u, 597u, 0u);
		const uint32_t reset_descriptor_pool_fixed_driver_begin = VK_MAKE_VERSION(512u, 671u, 0u);

		linear_descriptor_pools_enabled =
			p_device_properties.vendorID == RenderingContextDriver::Vendor::VENDOR_QUALCOMM &&
			(p_device_properties.driverVersion < reset_descriptor_pool_broken_driver_begin ||
				p_device_properties.driverVersion > reset_descriptor_pool_fixed_driver_begin);
	}

	if (p_driver_properties != nullptr) {
		// Workaround for Adreno drivers where ubershaders with a lot of constant literals crash the
		// compiler.
		driver_workarounds.disable_ubershaders =
			p_device_properties.vendorID == RenderingContextDriver::Vendor::VENDOR_QUALCOMM &&
			strstr(p_driver_properties->driverInfo, "Compiler Version: EV031.32.02.") != nullptr;
	}
}

void RenderingDeviceDriverVulkan::_get_device_properties()
{
	const RenderingContextDriverVulkan::Functions& functions = context_driver->functions_get();

	if (functions.GetPhysicalDeviceProperties2 != nullptr &&
		enabled_device_extension_names.has(VK_KHR_DRIVER_PROPERTIES_EXTENSION_NAME)) {
		VkPhysicalDeviceProperties2KHR device_props = {};
		device_props.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_PROPERTIES_2_KHR;

		VkPhysicalDeviceDriverPropertiesKHR driver_props = {};
		driver_props.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_DRIVER_PROPERTIES_KHR;
		device_props.pNext = &driver_props;

		functions.GetPhysicalDeviceProperties2(physical_device, &device_props);
		physical_device_properties = device_props.properties;

		_check_driver_workarounds(physical_device_properties, &driver_props);

	}
	else {
		vkGetPhysicalDeviceProperties(physical_device, &physical_device_properties);

		_check_driver_workarounds(physical_device_properties, nullptr);
	}
}

Error RenderingDeviceDriverVulkan::_check_device_features()
{
	vkGetPhysicalDeviceFeatures(physical_device, &physical_device_features);

	// Check for required features.
	if (!physical_device_features.imageCubeArray || !physical_device_features.independentBlend) {
		String error_string = vformat("Your GPU (%s) does not support the following features which "
									  "are required to use Vulkan-based renderers in Godot:\n\n",
			context_device.name);
		if (!physical_device_features.imageCubeArray) {
			error_string += "- No support for image cube arrays.\n";
		}
		if (!physical_device_features.independentBlend) {
			error_string += "- No support for independentBlend.\n";
		}
		error_string += "\nThis is usually a hardware limitation, so updating graphics drivers "
						"won't help in most cases.";

#if defined(ANDROID_ENABLED) || defined(IOS_ENABLED)
		// Android/iOS platform ports currently don't exit themselves when this method returns
		// `ERR_CANT_CREATE`.
		OS::alert(
			error_string + "\nClick OK to exit (black screen will be visible).");
#else
		OS::alert(error_string + "\nClick OK to exit.");
#endif

		return ERR_CANT_CREATE;
	}

	// Opt-in to the features we actually need/use. These can be changed in the future.
	// We do this for multiple reasons:
	//
	//	1. Certain features (like sparse* stuff) cause unnecessary internal driver allocations.
	//	2. Others like shaderStorageImageMultisample are a huge red flag
	//	   (MSAA + Storage is rarely needed).
	//	3. Most features when turned off aren't actually off (we just promise the driver not to use
	//them) 	   and it is validation what will complain. This allows us to target a minimum baseline.
	//
	// TODO: Allow the user to override these settings (i.e. turn off more stuff) using profiles
	// so they can target a broad range of HW. For example Mali HW does not have
	// shaderClipDistance/shaderCullDistance; thus validation would complain if such feature is
	// used; allowing them to fix the problem without even owning Mali HW to test on.
	//
	// The excluded features are:
	// - robustBufferAccess (can hamper performance on some hardware)
	// - occlusionQueryPrecise
	// - pipelineStatisticsQuery
	// - shaderStorageImageMultisample (unsupported by Intel Arc, prevents from using MSAA storage
	// accidentally)
	// - shaderResourceResidency
	// - sparseBinding (we don't use sparse features and enabling them cause extra internal
	// allocations inside the Vulkan driver we don't need)
	// - sparseResidencyBuffer
	// - sparseResidencyImage2D
	// - sparseResidencyImage3D
	// - sparseResidency2Samples
	// - sparseResidency4Samples
	// - sparseResidency8Samples
	// - sparseResidency16Samples
	// - sparseResidencyAliased
	// - inheritedQueries

#define VK_DEVICEFEATURE_ENABLE_IF(x)                                                              \
	if (physical_device_features.x) {                                                              \
		requested_device_features.x = physical_device_features.x;                                  \
	} \
	else                                                                                         \
		((void)0)

	requested_device_features = {};
	VK_DEVICEFEATURE_ENABLE_IF(fullDrawIndexUint32);
	VK_DEVICEFEATURE_ENABLE_IF(imageCubeArray);
	VK_DEVICEFEATURE_ENABLE_IF(independentBlend);
	VK_DEVICEFEATURE_ENABLE_IF(geometryShader);
	VK_DEVICEFEATURE_ENABLE_IF(tessellationShader);
	VK_DEVICEFEATURE_ENABLE_IF(sampleRateShading);
	VK_DEVICEFEATURE_ENABLE_IF(dualSrcBlend);
	VK_DEVICEFEATURE_ENABLE_IF(logicOp);
	VK_DEVICEFEATURE_ENABLE_IF(multiDrawIndirect);
	VK_DEVICEFEATURE_ENABLE_IF(drawIndirectFirstInstance);
	VK_DEVICEFEATURE_ENABLE_IF(depthClamp);
	VK_DEVICEFEATURE_ENABLE_IF(depthBiasClamp);
	VK_DEVICEFEATURE_ENABLE_IF(fillModeNonSolid);
	VK_DEVICEFEATURE_ENABLE_IF(depthBounds);
	VK_DEVICEFEATURE_ENABLE_IF(wideLines);
	VK_DEVICEFEATURE_ENABLE_IF(largePoints);
	VK_DEVICEFEATURE_ENABLE_IF(alphaToOne);
	VK_DEVICEFEATURE_ENABLE_IF(multiViewport);
	VK_DEVICEFEATURE_ENABLE_IF(samplerAnisotropy);
	VK_DEVICEFEATURE_ENABLE_IF(textureCompressionETC2);
	VK_DEVICEFEATURE_ENABLE_IF(textureCompressionASTC_LDR);
	VK_DEVICEFEATURE_ENABLE_IF(textureCompressionBC);
	VK_DEVICEFEATURE_ENABLE_IF(vertexPipelineStoresAndAtomics);
	VK_DEVICEFEATURE_ENABLE_IF(fragmentStoresAndAtomics);
	VK_DEVICEFEATURE_ENABLE_IF(shaderTessellationAndGeometryPointSize);
	VK_DEVICEFEATURE_ENABLE_IF(shaderImageGatherExtended);
	VK_DEVICEFEATURE_ENABLE_IF(shaderStorageImageExtendedFormats);
	VK_DEVICEFEATURE_ENABLE_IF(shaderStorageImageReadWithoutFormat);
	VK_DEVICEFEATURE_ENABLE_IF(shaderStorageImageWriteWithoutFormat);
	VK_DEVICEFEATURE_ENABLE_IF(shaderUniformBufferArrayDynamicIndexing);
	VK_DEVICEFEATURE_ENABLE_IF(shaderSampledImageArrayDynamicIndexing);
	VK_DEVICEFEATURE_ENABLE_IF(shaderStorageBufferArrayDynamicIndexing);
	VK_DEVICEFEATURE_ENABLE_IF(shaderStorageImageArrayDynamicIndexing);
	VK_DEVICEFEATURE_ENABLE_IF(shaderClipDistance);
	VK_DEVICEFEATURE_ENABLE_IF(shaderCullDistance);
	VK_DEVICEFEATURE_ENABLE_IF(shaderFloat64);
	VK_DEVICEFEATURE_ENABLE_IF(shaderInt64);
	VK_DEVICEFEATURE_ENABLE_IF(shaderInt16);
	VK_DEVICEFEATURE_ENABLE_IF(shaderResourceMinLod);
	VK_DEVICEFEATURE_ENABLE_IF(variableMultisampleRate);

	return OK;
}

static uint32_t _align_up(uint32_t size, uint32_t alignment)
{
	return (size + (alignment - 1)) & ~(alignment - 1);
}

Error RenderingDeviceDriverVulkan::_check_device_capabilities()
{
	// Fill device family and version.
	device_capabilities.device_family = DEVICE_VULKAN;
	device_capabilities.version_major = VK_API_VERSION_MAJOR(physical_device_properties.apiVersion);
	device_capabilities.version_minor = VK_API_VERSION_MINOR(physical_device_properties.apiVersion);

	// Cache extension availability we query often.
	framebuffer_depth_resolve =
		enabled_device_extension_names.has(VK_KHR_DEPTH_STENCIL_RESOLVE_EXTENSION_NAME);

	bool use_fdm_offsets = false;
	if (VulkanHooks::is_bound()) {
		use_fdm_offsets = VulkanHooks::use_fragment_density_offsets();
	}

	// References:
	// https://www.khronos.org/registry/vulkan/specs/1.2-extensions/man/html/VK_KHR_multiview.html
	// https://www.khronos.org/blog/vulkan-subgroup-tutorial
	const RenderingContextDriverVulkan::Functions& functions = context_driver->functions_get();
	if (functions.GetPhysicalDeviceFeatures2 != nullptr) {
		// We must check that the corresponding extension is present before assuming a feature as
		// enabled. See also: https://github.com/godotengine/godot/issues/65409

		void* next_features = nullptr;
		VkPhysicalDeviceVulkan12Features device_features_vk_1_2 = {};
		VkPhysicalDeviceShaderFloat16Int8FeaturesKHR shader_features = {};
		VkPhysicalDeviceBufferDeviceAddressFeaturesKHR buffer_device_address_features = {};
		VkPhysicalDeviceVulkanMemoryModelFeaturesKHR vulkan_memory_model_features = {};
		VkPhysicalDeviceFragmentShadingRateFeaturesKHR fsr_features = {};
		VkPhysicalDeviceFragmentDensityMapFeaturesEXT fdm_features = {};
		VkPhysicalDeviceFragmentDensityMapOffsetFeaturesQCOM fdmo_features_qcom = {};
		VkPhysicalDevice16BitStorageFeaturesKHR storage_feature = {};
		VkPhysicalDeviceMultiviewFeatures multiview_features = {};
		VkPhysicalDevicePipelineCreationCacheControlFeatures pipeline_cache_control_features = {};
		VkPhysicalDeviceVulkanMemoryModelFeatures memory_model_features = {};
		VkPhysicalDeviceAccelerationStructureFeaturesKHR acceleration_structure_features = {};
		VkPhysicalDeviceRayTracingPipelineFeaturesKHR raytracing_pipeline_features = {};
		VkPhysicalDeviceSynchronization2FeaturesKHR sync_2_features = {};
		VkPhysicalDeviceRayTracingValidationFeaturesNV raytracing_validation_features = {};

		const bool use_1_2_features = physical_device_properties.apiVersion >= VK_API_VERSION_1_2;
		if (use_1_2_features) {
			device_features_vk_1_2.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_VULKAN_1_2_FEATURES;
			device_features_vk_1_2.pNext = next_features;
			next_features = &device_features_vk_1_2;
		}
		else {
			if (enabled_device_extension_names.has(VK_KHR_SHADER_FLOAT16_INT8_EXTENSION_NAME)) {
				shader_features.sType =
					VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_SHADER_FLOAT16_INT8_FEATURES_KHR;
				shader_features.pNext = next_features;
				next_features = &shader_features;
			}
			if (enabled_device_extension_names.has(VK_KHR_BUFFER_DEVICE_ADDRESS_EXTENSION_NAME)) {
				buffer_device_address_features.sType =
					VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_BUFFER_DEVICE_ADDRESS_FEATURES_KHR;
				buffer_device_address_features.pNext = next_features;
				next_features = &buffer_device_address_features;
			}
			if (enabled_device_extension_names.has(VK_KHR_VULKAN_MEMORY_MODEL_EXTENSION_NAME)) {
				vulkan_memory_model_features.sType =
					VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_VULKAN_MEMORY_MODEL_FEATURES_KHR;
				vulkan_memory_model_features.pNext = next_features;
				next_features = &vulkan_memory_model_features;
			}
		}

		if (enabled_device_extension_names.has(VK_KHR_FRAGMENT_SHADING_RATE_EXTENSION_NAME)) {
			fsr_features.sType =
				VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_FRAGMENT_SHADING_RATE_FEATURES_KHR;
			fsr_features.pNext = next_features;
			next_features = &fsr_features;
		}

		if (enabled_device_extension_names.has(VK_EXT_FRAGMENT_DENSITY_MAP_EXTENSION_NAME)) {
			fdm_features.sType =
				VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_FRAGMENT_DENSITY_MAP_FEATURES_EXT;
			fdm_features.pNext = next_features;
			next_features = &fdm_features;
		}

		if (use_fdm_offsets && enabled_device_extension_names.has(
								   VK_QCOM_FRAGMENT_DENSITY_MAP_OFFSET_EXTENSION_NAME)) {
			fdmo_features_qcom.sType =
				VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_FRAGMENT_DENSITY_MAP_OFFSET_FEATURES_QCOM;
			fdmo_features_qcom.pNext = next_features;
			next_features = &fdmo_features_qcom;
		}

		if (enabled_device_extension_names.has(VK_KHR_16BIT_STORAGE_EXTENSION_NAME)) {
			storage_feature.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_16BIT_STORAGE_FEATURES_KHR;
			storage_feature.pNext = next_features;
			next_features = &storage_feature;
		}

		if (enabled_device_extension_names.has(VK_KHR_MULTIVIEW_EXTENSION_NAME)) {
			multiview_features.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_MULTIVIEW_FEATURES;
			multiview_features.pNext = next_features;
			next_features = &multiview_features;
		}

		if (enabled_device_extension_names.has(
				VK_EXT_PIPELINE_CREATION_CACHE_CONTROL_EXTENSION_NAME)) {
			pipeline_cache_control_features.sType =
				VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_PIPELINE_CREATION_CACHE_CONTROL_FEATURES;
			pipeline_cache_control_features.pNext = next_features;
			next_features = &pipeline_cache_control_features;
		}

		if (enabled_device_extension_names.has(VK_KHR_BUFFER_DEVICE_ADDRESS_EXTENSION_NAME)) {
			memory_model_features.sType =
				VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_VULKAN_MEMORY_MODEL_FEATURES;
			memory_model_features.pNext = next_features;
			next_features = &memory_model_features;
		}

		if (enabled_device_extension_names.has(VK_KHR_ACCELERATION_STRUCTURE_EXTENSION_NAME)) {
			acceleration_structure_features.sType =
				VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_ACCELERATION_STRUCTURE_FEATURES_KHR;
			acceleration_structure_features.pNext = next_features;
			next_features = &acceleration_structure_features;
		}

		if (enabled_device_extension_names.has(VK_KHR_RAY_TRACING_PIPELINE_EXTENSION_NAME)) {
			raytracing_pipeline_features.sType =
				VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_RAY_TRACING_PIPELINE_FEATURES_KHR;
			raytracing_pipeline_features.pNext = next_features;
			next_features = &raytracing_pipeline_features;
		}

		if (enabled_device_extension_names.has(VK_NV_RAY_TRACING_VALIDATION_EXTENSION_NAME)) {
			raytracing_validation_features.sType =
				VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_RAY_TRACING_VALIDATION_FEATURES_NV;
			raytracing_validation_features.pNext = next_features;
			next_features = &raytracing_validation_features;
		}

		if (enabled_device_extension_names.has(VK_KHR_SYNCHRONIZATION_2_EXTENSION_NAME)) {
			sync_2_features.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_SYNCHRONIZATION_2_FEATURES;
			sync_2_features.pNext = next_features;
			next_features = &sync_2_features;
		}

		VkPhysicalDeviceFeatures2 device_features_2 = {};
		device_features_2.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_FEATURES_2;
		device_features_2.pNext = next_features;
		functions.GetPhysicalDeviceFeatures2(physical_device, &device_features_2);

		if (use_1_2_features) {
#ifdef MACOS_ENABLED
			ERR_FAIL_COND_V_MSG(!device_features_vk_1_2.shaderSampledImageArrayNonUniformIndexing,
				ERR_CANT_CREATE,
				"Your GPU doesn't support shaderSampledImageArrayNonUniformIndexing which is "
				"required to use the Vulkan-based renderers in Godot.");
#endif
			if (enabled_device_extension_names.has(VK_KHR_SHADER_FLOAT16_INT8_EXTENSION_NAME)) {
				shader_capabilities.shader_float16_is_supported =
					device_features_vk_1_2.shaderFloat16;
				shader_capabilities.shader_int8_is_supported = device_features_vk_1_2.shaderInt8;
			}
			if (enabled_device_extension_names.has(VK_KHR_BUFFER_DEVICE_ADDRESS_EXTENSION_NAME)) {
				buffer_device_address_support = device_features_vk_1_2.bufferDeviceAddress;
			}
			if (enabled_device_extension_names.has(VK_KHR_VULKAN_MEMORY_MODEL_EXTENSION_NAME)) {
				vulkan_memory_model_support = device_features_vk_1_2.vulkanMemoryModel;
				vulkan_memory_model_device_scope_support =
					device_features_vk_1_2.vulkanMemoryModelDeviceScope;
			}
		}
		else {
			if (enabled_device_extension_names.has(VK_KHR_SHADER_FLOAT16_INT8_EXTENSION_NAME)) {
				shader_capabilities.shader_float16_is_supported = shader_features.shaderFloat16;
				shader_capabilities.shader_int8_is_supported = shader_features.shaderInt8;
			}
			if (enabled_device_extension_names.has(VK_KHR_BUFFER_DEVICE_ADDRESS_EXTENSION_NAME)) {
				buffer_device_address_support = buffer_device_address_features.bufferDeviceAddress;
			}
			if (enabled_device_extension_names.has(VK_KHR_VULKAN_MEMORY_MODEL_EXTENSION_NAME)) {
				vulkan_memory_model_support = vulkan_memory_model_features.vulkanMemoryModel;
				vulkan_memory_model_device_scope_support =
					vulkan_memory_model_features.vulkanMemoryModelDeviceScope;
			}
		}

		if (enabled_device_extension_names.has(VK_KHR_FRAGMENT_SHADING_RATE_EXTENSION_NAME)) {
			fsr_capabilities.pipeline_supported = fsr_features.pipelineFragmentShadingRate;
			fsr_capabilities.primitive_supported = fsr_features.primitiveFragmentShadingRate;
			fsr_capabilities.attachment_supported = fsr_features.attachmentFragmentShadingRate;
		}

		if (enabled_device_extension_names.has(VK_EXT_FRAGMENT_DENSITY_MAP_EXTENSION_NAME)) {
			fdm_capabilities.attachment_supported = fdm_features.fragmentDensityMap;
			fdm_capabilities.dynamic_attachment_supported = fdm_features.fragmentDensityMapDynamic;
			fdm_capabilities.non_subsampled_images_supported =
				fdm_features.fragmentDensityMapNonSubsampledImages;
		}

		if (enabled_device_extension_names.has(
				VK_QCOM_FRAGMENT_DENSITY_MAP_OFFSET_EXTENSION_NAME)) {
			fdm_capabilities.offset_supported = fdmo_features_qcom.fragmentDensityMapOffset;
		}

		// Multiple VRS techniques can't co-exist during the existence of one device, so we must
		// choose one at creation time and only report one of them as available.
		_choose_vrs_capabilities();

		if (enabled_device_extension_names.has(VK_KHR_MULTIVIEW_EXTENSION_NAME)) {
			multiview_capabilities.is_supported = multiview_features.multiview;
			multiview_capabilities.geometry_shader_is_supported =
				multiview_features.multiviewGeometryShader;
			multiview_capabilities.tessellation_shader_is_supported =
				multiview_features.multiviewTessellationShader;
		}

		if (enabled_device_extension_names.has(VK_KHR_16BIT_STORAGE_EXTENSION_NAME)) {
			storage_buffer_capabilities.storage_buffer_16_bit_access_is_supported =
				storage_feature.storageBuffer16BitAccess;
			storage_buffer_capabilities.uniform_and_storage_buffer_16_bit_access_is_supported =
				storage_feature.uniformAndStorageBuffer16BitAccess;
			storage_buffer_capabilities.storage_push_constant_16_is_supported =
				storage_feature.storagePushConstant16;
			storage_buffer_capabilities.storage_input_output_16 =
				storage_feature.storageInputOutput16;
		}

		if (enabled_device_extension_names.has(
				VK_EXT_PIPELINE_CREATION_CACHE_CONTROL_EXTENSION_NAME)) {
			pipeline_cache_control_support =
				pipeline_cache_control_features.pipelineCreationCacheControl;
		}

		if (enabled_device_extension_names.has(VK_EXT_DEVICE_FAULT_EXTENSION_NAME)) {
			device_fault_support = true;
		}
#if defined(VK_TRACK_DEVICE_MEMORY)
		if (enabled_device_extension_names.has(VK_EXT_DEVICE_MEMORY_REPORT_EXTENSION_NAME)) {
			device_memory_report_support = true;
		}
#endif

		if (enabled_device_extension_names.has(VK_KHR_ACCELERATION_STRUCTURE_EXTENSION_NAME)) {
			acceleration_structure_capabilities.acceleration_structure_support =
				acceleration_structure_features.accelerationStructure;
		}

		if (enabled_device_extension_names.has(VK_KHR_RAY_TRACING_PIPELINE_EXTENSION_NAME)) {
			raytracing_capabilities.raytracing_pipeline_support =
				raytracing_pipeline_features.rayTracingPipeline;
			raytracing_capabilities.validation =
				raytracing_validation_features.rayTracingValidation;
		}
	}

	if (functions.GetPhysicalDeviceProperties2 != nullptr) {
		void* next_properties = nullptr;
		VkPhysicalDeviceFragmentShadingRatePropertiesKHR fsr_properties = {};
		VkPhysicalDeviceFragmentDensityMapPropertiesEXT fdm_properties = {};
		VkPhysicalDeviceFragmentDensityMapOffsetPropertiesQCOM fdmo_properties = {};
		VkPhysicalDeviceMultiviewProperties multiview_properties = {};
		VkPhysicalDeviceSubgroupProperties subgroup_properties = {};
		VkPhysicalDeviceSubgroupSizeControlProperties subgroup_size_control_properties = {};
		VkPhysicalDeviceAccelerationStructurePropertiesKHR acceleration_structure_properties = {};
		VkPhysicalDeviceRayTracingPipelinePropertiesKHR raytracing_properties = {};
		VkPhysicalDeviceProperties2 physical_device_properties_2 = {};

		const bool use_1_1_properties = physical_device_properties.apiVersion >= VK_API_VERSION_1_1;
		if (use_1_1_properties) {
			subgroup_properties.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_SUBGROUP_PROPERTIES;
			subgroup_properties.pNext = next_properties;
			next_properties = &subgroup_properties;

			subgroup_capabilities.size_control_is_supported =
				enabled_device_extension_names.has(VK_EXT_SUBGROUP_SIZE_CONTROL_EXTENSION_NAME);
			if (subgroup_capabilities.size_control_is_supported) {
				subgroup_size_control_properties.sType =
					VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_SUBGROUP_SIZE_CONTROL_PROPERTIES;
				subgroup_size_control_properties.pNext = next_properties;
				next_properties = &subgroup_size_control_properties;
			}
		}

		if (multiview_capabilities.is_supported) {
			multiview_properties.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_MULTIVIEW_PROPERTIES;
			multiview_properties.pNext = next_properties;
			next_properties = &multiview_properties;
		}

		if (fsr_capabilities.attachment_supported) {
			fsr_properties.sType =
				VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_FRAGMENT_SHADING_RATE_PROPERTIES_KHR;
			fsr_properties.pNext = next_properties;
			next_properties = &fsr_properties;
		}

		if (fdm_capabilities.attachment_supported) {
			fdm_properties.sType =
				VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_FRAGMENT_DENSITY_MAP_PROPERTIES_EXT;
			fdm_properties.pNext = next_properties;
			next_properties = &fdm_properties;
		}

		if (fdm_capabilities.offset_supported) {
			fdmo_properties.sType =
				VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_FRAGMENT_DENSITY_MAP_OFFSET_PROPERTIES_QCOM;
			fdmo_properties.pNext = next_properties;
			next_properties = &fdmo_properties;
		}

		if (acceleration_structure_capabilities.acceleration_structure_support) {
			acceleration_structure_properties.sType =
				VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_ACCELERATION_STRUCTURE_PROPERTIES_KHR;
			acceleration_structure_properties.pNext = next_properties;
			next_properties = &acceleration_structure_properties;
		}

		if (raytracing_capabilities.raytracing_pipeline_support) {
			raytracing_properties.sType =
				VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_RAY_TRACING_PIPELINE_PROPERTIES_KHR;
			raytracing_properties.pNext = next_properties;
			next_properties = &raytracing_properties;
		}

		physical_device_properties_2.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_PROPERTIES_2;
		physical_device_properties_2.pNext = next_properties;
		functions.GetPhysicalDeviceProperties2(physical_device, &physical_device_properties_2);

		subgroup_capabilities.size = subgroup_properties.subgroupSize;
		subgroup_capabilities.min_size = subgroup_properties.subgroupSize;
		subgroup_capabilities.max_size = subgroup_properties.subgroupSize;
		subgroup_capabilities.supported_stages = subgroup_properties.supportedStages;
		subgroup_capabilities.supported_operations = subgroup_properties.supportedOperations;

		// Note: quadOperationsInAllStages will be true if:
		// - supportedStages has VK_SHADER_STAGE_ALL_GRAPHICS + VK_SHADER_STAGE_COMPUTE_BIT.
		// - supportedOperations has VK_SUBGROUP_FEATURE_QUAD_BIT.
		subgroup_capabilities.quad_operations_in_all_stages =
			subgroup_properties.quadOperationsInAllStages;

		if (subgroup_capabilities.size_control_is_supported &&
			(subgroup_size_control_properties.requiredSubgroupSizeStages &
				VK_SHADER_STAGE_COMPUTE_BIT)) {
			subgroup_capabilities.min_size = subgroup_size_control_properties.minSubgroupSize;
			subgroup_capabilities.max_size = subgroup_size_control_properties.maxSubgroupSize;
		}

		if (fsr_capabilities.pipeline_supported || fsr_capabilities.primitive_supported ||
			fsr_capabilities.attachment_supported) {
			print_verbose("- Vulkan Fragment Shading Rate supported:");
			if (fsr_capabilities.pipeline_supported) {
				print_verbose("  Pipeline fragment shading rate");
			}
			if (fsr_capabilities.primitive_supported) {
				print_verbose("  Primitive fragment shading rate");
			}
			if (fsr_capabilities.attachment_supported) {
				// TODO: Expose these somehow to the end user.
				fsr_capabilities.min_texel_size.x =
					fsr_properties.minFragmentShadingRateAttachmentTexelSize.width;
				fsr_capabilities.min_texel_size.y =
					fsr_properties.minFragmentShadingRateAttachmentTexelSize.height;
				fsr_capabilities.max_texel_size.x =
					fsr_properties.maxFragmentShadingRateAttachmentTexelSize.width;
				fsr_capabilities.max_texel_size.y =
					fsr_properties.maxFragmentShadingRateAttachmentTexelSize.height;
				fsr_capabilities.max_fragment_size.x =
					fsr_properties.maxFragmentSize.width; // either 4 or 8
				fsr_capabilities.max_fragment_size.y =
					fsr_properties.maxFragmentSize.height; // generally the same as width

				print_verbose(
					String("  Attachment fragment shading rate") + String(", min texel size: (") +
					itos(fsr_capabilities.min_texel_size.x) + String(", ") +
					itos(fsr_capabilities.min_texel_size.y) + String(")") +
					String(", max texel size: (") + itos(fsr_capabilities.max_texel_size.x) +
					String(", ") + itos(fsr_capabilities.max_texel_size.y) + String(")") +
					String(", max fragment size: (") + itos(fsr_capabilities.max_fragment_size.x) +
					String(", ") + itos(fsr_capabilities.max_fragment_size.y) + String(")"));
			}

		}
		else {
			print_verbose("- Vulkan Variable Rate Shading not supported");
		}

		if (fdm_capabilities.attachment_supported ||
			fdm_capabilities.dynamic_attachment_supported ||
			fdm_capabilities.non_subsampled_images_supported) {
			fdm_capabilities.min_texel_size.x = fdm_properties.minFragmentDensityTexelSize.width;
			fdm_capabilities.min_texel_size.y = fdm_properties.minFragmentDensityTexelSize.height;
			fdm_capabilities.max_texel_size.x = fdm_properties.maxFragmentDensityTexelSize.width;
			fdm_capabilities.max_texel_size.y = fdm_properties.maxFragmentDensityTexelSize.height;
			fdm_capabilities.invocations_supported = fdm_properties.fragmentDensityInvocations;

			print_verbose(String("- Vulkan Fragment Density Map supported") +
						  String(", min texel size: (") + itos(fdm_capabilities.min_texel_size.x) +
						  String(", ") + itos(fdm_capabilities.min_texel_size.y) + String(")") +
						  String(", max texel size: (") + itos(fdm_capabilities.max_texel_size.x) +
						  String(", ") + itos(fdm_capabilities.max_texel_size.y) + String(")"));

			if (fdm_capabilities.dynamic_attachment_supported) {
				print_verbose("  - dynamic fragment density map supported");
			}

			if (fdm_capabilities.non_subsampled_images_supported) {
				print_verbose("  - non-subsampled images supported");
			}
		}
		else {
			print_verbose("- Vulkan Fragment Density Map not supported");
		}

		if (fdm_capabilities.offset_supported) {
			print_verbose("- Vulkan Fragment Density Map Offset supported");

			fdm_capabilities.offset_granularity.x =
				fdmo_properties.fragmentDensityOffsetGranularity.width;
			fdm_capabilities.offset_granularity.y =
				fdmo_properties.fragmentDensityOffsetGranularity.height;

			print_verbose(vformat("  Offset granularity: (%d, %d)",
				fdm_capabilities.offset_granularity.x, fdm_capabilities.offset_granularity.y));
		}
		else if (use_fdm_offsets) {
			print_verbose("- Vulkan Fragment Density Map Offset not supported");
		}

		if (multiview_capabilities.is_supported) {
			multiview_capabilities.max_view_count = multiview_properties.maxMultiviewViewCount;
			multiview_capabilities.max_instance_count =
				multiview_properties.maxMultiviewInstanceIndex;

			print_verbose("- Vulkan multiview supported:");
			print_verbose("  max view count: " + itos(multiview_capabilities.max_view_count));
			print_verbose("  max instances: " + itos(multiview_capabilities.max_instance_count));
		}
		else {
			print_verbose("- Vulkan multiview not supported");
		}

		print_verbose("- Vulkan subgroup:");
		print_verbose("  size: " + itos(subgroup_capabilities.size));
		print_verbose("  min size: " + itos(subgroup_capabilities.min_size));
		print_verbose("  max size: " + itos(subgroup_capabilities.max_size));
		print_verbose("  stages: " + subgroup_capabilities.supported_stages_desc());
		print_verbose("  supported ops: " + subgroup_capabilities.supported_operations_desc());
		if (subgroup_capabilities.quad_operations_in_all_stages) {
			print_verbose("  quad operations in all stages");
		}

		if (acceleration_structure_capabilities.acceleration_structure_support) {
			print_verbose("- Vulkan Acceleration Structure supported");
			acceleration_structure_capabilities
				.min_acceleration_structure_scratch_offset_alignment =
				acceleration_structure_properties.minAccelerationStructureScratchOffsetAlignment;
			print_verbose("  min acceleration structure scratch offset alignment: " +
						  itos(acceleration_structure_capabilities
								   .min_acceleration_structure_scratch_offset_alignment));
		}
		else {
			print_verbose("- Vulkan Acceleration Structure not supported");
		}

		if (raytracing_capabilities.raytracing_pipeline_support) {
			raytracing_capabilities.shader_group_handle_size =
				raytracing_properties.shaderGroupHandleSize;
			raytracing_capabilities.shader_group_handle_alignment =
				raytracing_properties.shaderGroupHandleAlignment;
			raytracing_capabilities.shader_group_handle_size_aligned =
				_align_up(raytracing_capabilities.shader_group_handle_size,
					raytracing_capabilities.shader_group_handle_alignment);
			raytracing_capabilities.shader_group_base_alignment =
				raytracing_properties.shaderGroupBaseAlignment;

			print_verbose("- Vulkan Raytracing supported");
			print_verbose("  shader group handle size: " +
						  itos(raytracing_capabilities.shader_group_handle_size));
			print_verbose("  shader group handle alignment: " +
						  itos(raytracing_capabilities.shader_group_handle_alignment));
			print_verbose("  shader group handle size aligned: " +
						  itos(raytracing_capabilities.shader_group_handle_size_aligned));
			print_verbose("  shader group base alignment: " +
						  itos(raytracing_capabilities.shader_group_base_alignment));
		}
		else {
			print_verbose("- Vulkan Raytracing not supported");
		}
	}

	return OK;
}

void RenderingDeviceDriverVulkan::_choose_vrs_capabilities()
{
	bool prefer_fdm_on_qualcomm =
		physical_device_properties.vendorID == RenderingContextDriver::Vendor::VENDOR_QUALCOMM;
	if (fdm_capabilities.attachment_supported &&
		(!fsr_capabilities.attachment_supported || prefer_fdm_on_qualcomm)) {
		// If available, we prefer using fragment density maps on Qualcomm as they adjust tile
		// distribution when using this technique. Performance as a result is higher than when using
		// fragment shading rate.
		fsr_capabilities = FragmentShadingRateCapabilities();
	}
	else if (fsr_capabilities.attachment_supported) {
		// Disable any possibility of fragment density maps being used.
		fdm_capabilities = FragmentDensityMapCapabilities();
	}
	else {
		// Do not report or enable any VRS capabilities if attachment is not supported.
		fsr_capabilities = FragmentShadingRateCapabilities();
		fdm_capabilities = FragmentDensityMapCapabilities();
	}
}

Error RenderingDeviceDriverVulkan::_add_queue_create_info(
	LocalVector<VkDeviceQueueCreateInfo>& r_queue_create_info)
{
	uint32_t queue_family_count = queue_family_properties.size();
	queue_families.resize(queue_family_count);

	VkQueueFlags queue_flags_mask =
		VK_QUEUE_GRAPHICS_BIT | VK_QUEUE_COMPUTE_BIT | VK_QUEUE_TRANSFER_BIT;
	const uint32_t max_queue_count_per_family = 1;
	static const float queue_priorities[max_queue_count_per_family] = {};
	for (uint32_t i = 0; i < queue_family_count; i++) {
		if ((queue_family_properties[i].queueFlags & queue_flags_mask) == 0) {
			// We ignore creating queues in families that don't support any of the operations we
			// require.
			continue;
		}

		VkDeviceQueueCreateInfo create_info = {};
		create_info.sType = VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO;
		create_info.queueFamilyIndex = i;
		create_info.queueCount =
			MIN(queue_family_properties[i].queueCount, max_queue_count_per_family);
		create_info.pQueuePriorities = queue_priorities;
		r_queue_create_info.push_back(create_info);

		// Prepare the vectors where the queues will be filled out.
		queue_families[i].resize(create_info.queueCount);
	}

	return OK;
}

Error RenderingDeviceDriverVulkan::_initialize_device(
	const LocalVector<VkDeviceQueueCreateInfo>& p_queue_create_info)
{
	TightLocalVector<const char*> enabled_extension_names;
	enabled_extension_names.reserve(enabled_device_extension_names.size());
	for (const CharString& extension_name : enabled_device_extension_names) {
		enabled_extension_names.push_back(extension_name.ptr());
	}

	void* create_info_next = nullptr;
	VkPhysicalDeviceShaderFloat16Int8FeaturesKHR shader_features = {};
	shader_features.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_SHADER_FLOAT16_INT8_FEATURES_KHR;
	shader_features.pNext = create_info_next;
	shader_features.shaderFloat16 = shader_capabilities.shader_float16_is_supported;
	shader_features.shaderInt8 = shader_capabilities.shader_int8_is_supported;
	create_info_next = &shader_features;

	VkPhysicalDeviceBufferDeviceAddressFeaturesKHR buffer_device_address_features = {};
	if (buffer_device_address_support) {
		buffer_device_address_features.sType =
			VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_BUFFER_DEVICE_ADDRESS_FEATURES_KHR;
		buffer_device_address_features.pNext = create_info_next;
		buffer_device_address_features.bufferDeviceAddress = buffer_device_address_support;
		create_info_next = &buffer_device_address_features;
	}

	VkPhysicalDeviceVulkanMemoryModelFeaturesKHR vulkan_memory_model_features = {};
	if (vulkan_memory_model_support && vulkan_memory_model_device_scope_support) {
		vulkan_memory_model_features.sType =
			VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_VULKAN_MEMORY_MODEL_FEATURES_KHR;
		vulkan_memory_model_features.pNext = create_info_next;
		vulkan_memory_model_features.vulkanMemoryModel = vulkan_memory_model_support;
		vulkan_memory_model_features.vulkanMemoryModelDeviceScope =
			vulkan_memory_model_device_scope_support;
		create_info_next = &vulkan_memory_model_features;
	}

	VkPhysicalDeviceFragmentShadingRateFeaturesKHR fsr_features = {};
	if (fsr_capabilities.pipeline_supported || fsr_capabilities.primitive_supported ||
		fsr_capabilities.attachment_supported) {
		fsr_features.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_FRAGMENT_SHADING_RATE_FEATURES_KHR;
		fsr_features.pNext = create_info_next;
		fsr_features.pipelineFragmentShadingRate = fsr_capabilities.pipeline_supported;
		fsr_features.primitiveFragmentShadingRate = fsr_capabilities.primitive_supported;
		fsr_features.attachmentFragmentShadingRate = fsr_capabilities.attachment_supported;
		create_info_next = &fsr_features;
	}

	VkPhysicalDeviceFragmentDensityMapFeaturesEXT fdm_features = {};
	if (fdm_capabilities.attachment_supported || fdm_capabilities.dynamic_attachment_supported ||
		fdm_capabilities.non_subsampled_images_supported) {
		fdm_features.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_FRAGMENT_DENSITY_MAP_FEATURES_EXT;
		fdm_features.pNext = create_info_next;
		fdm_features.fragmentDensityMap = fdm_capabilities.attachment_supported;
		fdm_features.fragmentDensityMapDynamic = fdm_capabilities.dynamic_attachment_supported;
		fdm_features.fragmentDensityMapNonSubsampledImages =
			fdm_capabilities.non_subsampled_images_supported;
		create_info_next = &fdm_features;
	}

	VkPhysicalDeviceFragmentDensityMapOffsetFeaturesQCOM fdm_offset_features = {};
	if (fdm_capabilities.offset_supported) {
		fdm_offset_features.sType =
			VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_FRAGMENT_DENSITY_MAP_OFFSET_FEATURES_QCOM;
		fdm_offset_features.pNext = create_info_next;
		fdm_offset_features.fragmentDensityMapOffset = VK_TRUE;
		create_info_next = &fdm_offset_features;
	}

	VkPhysicalDevicePipelineCreationCacheControlFeatures pipeline_cache_control_features = {};
	if (pipeline_cache_control_support) {
		pipeline_cache_control_features.sType =
			VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_PIPELINE_CREATION_CACHE_CONTROL_FEATURES;
		pipeline_cache_control_features.pNext = create_info_next;
		pipeline_cache_control_features.pipelineCreationCacheControl =
			pipeline_cache_control_support;
		create_info_next = &pipeline_cache_control_features;
	}

	VkPhysicalDeviceFaultFeaturesEXT device_fault_features = {};
	if (device_fault_support) {
		device_fault_features.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_FAULT_FEATURES_EXT;
		device_fault_features.pNext = create_info_next;
		create_info_next = &device_fault_features;
	}

#if defined(VK_TRACK_DEVICE_MEMORY)
	VkDeviceDeviceMemoryReportCreateInfoEXT memory_report_info = {};
	if (device_memory_report_support) {
		memory_report_info.sType = VK_STRUCTURE_TYPE_DEVICE_DEVICE_MEMORY_REPORT_CREATE_INFO_EXT;
		memory_report_info.pfnUserCallback = RenderingContextDriverVulkan::memory_report_callback;
		memory_report_info.pNext = create_info_next;
		memory_report_info.flags = 0;
		memory_report_info.pUserData = this;

		create_info_next = &memory_report_info;
	}
#endif

	VkPhysicalDeviceAccelerationStructureFeaturesKHR acceleration_structure_features = {};
	if (acceleration_structure_capabilities.acceleration_structure_support) {
		acceleration_structure_features.sType =
			VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_ACCELERATION_STRUCTURE_FEATURES_KHR;
		acceleration_structure_features.pNext = create_info_next;
		acceleration_structure_features.accelerationStructure =
			acceleration_structure_capabilities.acceleration_structure_support;
		create_info_next = &acceleration_structure_features;
	}

	VkPhysicalDeviceRayTracingPipelineFeaturesKHR raytracing_pipeline_features = {};
	if (raytracing_capabilities.raytracing_pipeline_support) {
		raytracing_pipeline_features.sType =
			VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_RAY_TRACING_PIPELINE_FEATURES_KHR;
		raytracing_pipeline_features.pNext = create_info_next;
		raytracing_pipeline_features.rayTracingPipeline =
			raytracing_capabilities.raytracing_pipeline_support;
		create_info_next = &raytracing_pipeline_features;
	}

	VkPhysicalDeviceRayTracingValidationFeaturesNV raytracing_validation_features = {};
	if (raytracing_capabilities.validation) {
		raytracing_validation_features.sType =
			VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_RAY_TRACING_VALIDATION_FEATURES_NV;
		raytracing_validation_features.pNext = create_info_next;
		raytracing_validation_features.rayTracingValidation = raytracing_capabilities.validation;
		create_info_next = &raytracing_validation_features;
	}

	VkPhysicalDeviceVulkan11Features vulkan_1_1_features = {};
	VkPhysicalDevice16BitStorageFeaturesKHR storage_features = {};
	VkPhysicalDeviceMultiviewFeatures multiview_features = {};
	const bool enable_1_2_features = physical_device_properties.apiVersion >= VK_API_VERSION_1_2;
	if (enable_1_2_features) {
		// In Vulkan 1.2 and newer we use a newer struct to enable various features.
		vulkan_1_1_features.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_VULKAN_1_1_FEATURES;
		vulkan_1_1_features.pNext = create_info_next;
		vulkan_1_1_features.storageBuffer16BitAccess =
			storage_buffer_capabilities.storage_buffer_16_bit_access_is_supported;
		vulkan_1_1_features.uniformAndStorageBuffer16BitAccess =
			storage_buffer_capabilities.uniform_and_storage_buffer_16_bit_access_is_supported;
		vulkan_1_1_features.storagePushConstant16 =
			storage_buffer_capabilities.storage_push_constant_16_is_supported;
		vulkan_1_1_features.storageInputOutput16 =
			storage_buffer_capabilities.storage_input_output_16;
		vulkan_1_1_features.multiview = multiview_capabilities.is_supported;
		vulkan_1_1_features.multiviewGeometryShader =
			multiview_capabilities.geometry_shader_is_supported;
		vulkan_1_1_features.multiviewTessellationShader =
			multiview_capabilities.tessellation_shader_is_supported;
		vulkan_1_1_features.variablePointersStorageBuffer = 0;
		vulkan_1_1_features.variablePointers = 0;
		vulkan_1_1_features.protectedMemory = 0;
		vulkan_1_1_features.samplerYcbcrConversion = 0;
		vulkan_1_1_features.shaderDrawParameters = 0;
		create_info_next = &vulkan_1_1_features;
	}
	else {
		// On Vulkan 1.0 and 1.1 we use our older structs to initialize these features.
		storage_features.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_16BIT_STORAGE_FEATURES_KHR;
		storage_features.pNext = create_info_next;
		storage_features.storageBuffer16BitAccess =
			storage_buffer_capabilities.storage_buffer_16_bit_access_is_supported;
		storage_features.uniformAndStorageBuffer16BitAccess =
			storage_buffer_capabilities.uniform_and_storage_buffer_16_bit_access_is_supported;
		storage_features.storagePushConstant16 =
			storage_buffer_capabilities.storage_push_constant_16_is_supported;
		storage_features.storageInputOutput16 = storage_buffer_capabilities.storage_input_output_16;
		create_info_next = &storage_features;

		const bool enable_1_1_features =
			physical_device_properties.apiVersion >= VK_API_VERSION_1_1;
		if (enable_1_1_features) {
			multiview_features.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_MULTIVIEW_FEATURES;
			multiview_features.pNext = create_info_next;
			multiview_features.multiview = multiview_capabilities.is_supported;
			multiview_features.multiviewGeometryShader =
				multiview_capabilities.geometry_shader_is_supported;
			multiview_features.multiviewTessellationShader =
				multiview_capabilities.tessellation_shader_is_supported;
			create_info_next = &multiview_features;
		}
	}

	VkDeviceCreateInfo create_info = {};
	create_info.sType = VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO;
	create_info.pNext = create_info_next;
	create_info.queueCreateInfoCount = p_queue_create_info.size();
	create_info.pQueueCreateInfos = p_queue_create_info.ptr();
	create_info.enabledExtensionCount = enabled_extension_names.size();
	create_info.ppEnabledExtensionNames = enabled_extension_names.ptr();
	create_info.pEnabledFeatures = &requested_device_features;

	if (VulkanHooks::is_bound()) {
		bool device_created = VulkanHooks::create_vulkan_device(&create_info, &vk_device);
		ERR_FAIL_COND_V_MSG(!device_created, ERR_CANT_CREATE,
			"Couldn't create a Vulkan device through VulkanHooks.");
	}
	else {
		VkResult err = vkCreateDevice(physical_device, &create_info,
			VKC::get_allocation_callbacks(VK_OBJECT_TYPE_DEVICE), &vk_device);
		ERR_FAIL_COND_V_MSG(err != VK_SUCCESS, ERR_CANT_CREATE,
			vformat("Couldn't create Vulkan device (VkResult error %d).", err));
	}

	for (uint32_t i = 0; i < queue_families.size(); i++) {
		for (uint32_t j = 0; j < queue_families[i].size(); j++) {
			vkGetDeviceQueue(vk_device, i, j, &queue_families[i][j].queue);
		}
	}

	const RenderingContextDriverVulkan::Functions& functions = context_driver->functions_get();
	if (functions.GetDeviceProcAddr != nullptr) {
		device_functions.CreateSwapchainKHR = PFN_vkCreateSwapchainKHR(
			functions.GetDeviceProcAddr(vk_device, "vkCreateSwapchainKHR"));
		device_functions.DestroySwapchainKHR = PFN_vkDestroySwapchainKHR(
			functions.GetDeviceProcAddr(vk_device, "vkDestroySwapchainKHR"));
		device_functions.GetSwapchainImagesKHR = PFN_vkGetSwapchainImagesKHR(
			functions.GetDeviceProcAddr(vk_device, "vkGetSwapchainImagesKHR"));
		device_functions.AcquireNextImageKHR = PFN_vkAcquireNextImageKHR(
			functions.GetDeviceProcAddr(vk_device, "vkAcquireNextImageKHR"));
		device_functions.QueuePresentKHR =
			PFN_vkQueuePresentKHR(functions.GetDeviceProcAddr(vk_device, "vkQueuePresentKHR"));

		if (enabled_device_extension_names.has(VK_KHR_CREATE_RENDERPASS_2_EXTENSION_NAME)) {
			device_functions.CreateRenderPass2KHR = PFN_vkCreateRenderPass2KHR(
				functions.GetDeviceProcAddr(vk_device, "vkCreateRenderPass2KHR"));
			device_functions.EndRenderPass2KHR = PFN_vkCmdEndRenderPass2KHR(
				functions.GetDeviceProcAddr(vk_device, "vkCmdEndRenderPass2KHR"));
		}

		// Debug marker extensions.
		if (enabled_device_extension_names.has(VK_EXT_DEBUG_MARKER_EXTENSION_NAME)) {
			device_functions.CmdDebugMarkerBeginEXT =
				(PFN_vkCmdDebugMarkerBeginEXT)functions.GetDeviceProcAddr(
					vk_device, "vkCmdDebugMarkerBeginEXT");
			device_functions.CmdDebugMarkerEndEXT =
				(PFN_vkCmdDebugMarkerEndEXT)functions.GetDeviceProcAddr(
					vk_device, "vkCmdDebugMarkerEndEXT");
			device_functions.CmdDebugMarkerInsertEXT =
				(PFN_vkCmdDebugMarkerInsertEXT)functions.GetDeviceProcAddr(
					vk_device, "vkCmdDebugMarkerInsertEXT");
			device_functions.DebugMarkerSetObjectNameEXT =
				(PFN_vkDebugMarkerSetObjectNameEXT)functions.GetDeviceProcAddr(
					vk_device, "vkDebugMarkerSetObjectNameEXT");
		}

		// Debug device fault extension.
		if (device_fault_support) {
			device_functions.GetDeviceFaultInfoEXT =
				(PFN_vkGetDeviceFaultInfoEXT)functions.GetDeviceProcAddr(
					vk_device, "vkGetDeviceFaultInfoEXT");
		}

		// Device raytracing extensions.
		if (enabled_device_extension_names.has(VK_KHR_ACCELERATION_STRUCTURE_EXTENSION_NAME)) {
			device_functions.CreateAccelerationStructureKHR = PFN_vkCreateAccelerationStructureKHR(
				functions.GetDeviceProcAddr(vk_device, "vkCreateAccelerationStructureKHR"));
			device_functions.DestroyAccelerationStructureKHR =
				PFN_vkDestroyAccelerationStructureKHR(
					functions.GetDeviceProcAddr(vk_device, "vkDestroyAccelerationStructureKHR"));
			device_functions.GetAccelerationStructureBuildSizesKHR =
				PFN_vkGetAccelerationStructureBuildSizesKHR(functions.GetDeviceProcAddr(
					vk_device, "vkGetAccelerationStructureBuildSizesKHR"));
			device_functions.CmdBuildAccelerationStructuresKHR =
				PFN_vkCmdBuildAccelerationStructuresKHR(
					functions.GetDeviceProcAddr(vk_device, "vkCmdBuildAccelerationStructuresKHR"));
		}

		if (enabled_device_extension_names.has(VK_KHR_RAY_TRACING_PIPELINE_EXTENSION_NAME)) {
			device_functions.CreateRaytracingPipelinesKHR = PFN_vkCreateRayTracingPipelinesKHR(
				functions.GetDeviceProcAddr(vk_device, "vkCreateRayTracingPipelinesKHR"));
			device_functions.GetRayTracingShaderGroupHandlesKHR =
				PFN_vkGetRayTracingShaderGroupHandlesKHR(
					functions.GetDeviceProcAddr(vk_device, "vkGetRayTracingShaderGroupHandlesKHR"));
			device_functions.CmdTraceRaysKHR =
				PFN_vkCmdTraceRaysKHR(functions.GetDeviceProcAddr(vk_device, "vkCmdTraceRaysKHR"));
		}
	}

	return OK;
}

Error RenderingDeviceDriverVulkan::_initialize_allocator()
{
	VmaAllocatorCreateInfo allocator_info = {};
	allocator_info.physicalDevice = physical_device;
	allocator_info.device = vk_device;
	allocator_info.instance = context_driver->instance_get();
	const bool use_1_3_features = physical_device_properties.apiVersion >= VK_API_VERSION_1_3;
	if (use_1_3_features) {
		allocator_info.flags = Utils::set_flag(allocator_info.flags, VMA_ALLOCATOR_CREATE_KHR_MAINTENANCE5_BIT);
	}
	if (buffer_device_address_support) {
		allocator_info.flags = Utils::set_flag(allocator_info.flags, VMA_ALLOCATOR_CREATE_BUFFER_DEVICE_ADDRESS_BIT);
	}
	VkResult err = vmaCreateAllocator(&allocator_info, &allocator);
	ERR_FAIL_COND_V_MSG(err, ERR_CANT_CREATE,
		vformat("Couldn't create Vulkan memory allocator (VkResult error %d).", err));

	return OK;
}

Error RenderingDeviceDriverVulkan::_initialize_pipeline_cache()
{
	pipelines_cache.buffer.resize(sizeof(PipelineCacheHeader));
	PipelineCacheHeader* header = (PipelineCacheHeader*)(pipelines_cache.buffer.ptrw());
	*header = {};
	header->magic = 868 + VK_PIPELINE_CACHE_HEADER_VERSION_ONE;
	header->device_id = physical_device_properties.deviceID;
	header->vendor_id = physical_device_properties.vendorID;
	header->driver_version = physical_device_properties.driverVersion;
	memcpy(header->uuid, physical_device_properties.pipelineCacheUUID, VK_UUID_SIZE);
	header->driver_abi = sizeof(void*);

	pipeline_cache_id =
		String::hex_encode_buffer(physical_device_properties.pipelineCacheUUID, VK_UUID_SIZE);
	pipeline_cache_id += "-driver-" + itos(physical_device_properties.driverVersion);

	return OK;
}

static void _convert_subpass_attachments(const VkAttachmentReference2* p_attachment_references_2,
	uint32_t p_attachment_references_count,
	TightLocalVector<VkAttachmentReference>& r_attachment_references)
{
	r_attachment_references.resize(p_attachment_references_count);
	for (uint32_t i = 0; i < p_attachment_references_count; i++) {
		// Ignore sType, pNext and aspectMask (which is currently unused).
		r_attachment_references[i].attachment = p_attachment_references_2[i].attachment;
		r_attachment_references[i].layout = p_attachment_references_2[i].layout;
	}
}

VkResult RenderingDeviceDriverVulkan::_create_render_pass(VkDevice p_device,
	const VkRenderPassCreateInfo2* p_create_info, const VkAllocationCallbacks* p_allocator,
	VkRenderPass* p_render_pass)
{
	if (device_functions.CreateRenderPass2KHR != nullptr) {
		return device_functions.CreateRenderPass2KHR(
			p_device, p_create_info, p_allocator, p_render_pass);
	}
	else {
		// Compatibility fallback with regular create render pass but by converting the inputs from
		// the newer version to the older one.
		TightLocalVector<VkAttachmentDescription> attachments;
		attachments.resize(p_create_info->attachmentCount);
		for (uint32_t i = 0; i < p_create_info->attachmentCount; i++) {
			// Ignores sType and pNext from the attachment.
			const VkAttachmentDescription2& src = p_create_info->pAttachments[i];
			VkAttachmentDescription& dst = attachments[i];
			dst.flags = src.flags;
			dst.format = src.format;
			dst.samples = src.samples;
			dst.loadOp = src.loadOp;
			dst.storeOp = src.storeOp;
			dst.stencilLoadOp = src.stencilLoadOp;
			dst.stencilStoreOp = src.stencilStoreOp;
			dst.initialLayout = src.initialLayout;
			dst.finalLayout = src.finalLayout;
		}

		const uint32_t attachment_vectors_per_subpass = 4;
		TightLocalVector<TightLocalVector<VkAttachmentReference>> subpasses_attachments;
		TightLocalVector<VkSubpassDescription> subpasses;
		subpasses_attachments.resize(p_create_info->subpassCount * attachment_vectors_per_subpass);
		subpasses.resize(p_create_info->subpassCount);

		for (uint32_t i = 0; i < p_create_info->subpassCount; i++) {
			const uint32_t vector_base_index = i * attachment_vectors_per_subpass;
			const uint32_t input_attachments_index = vector_base_index + 0;
			const uint32_t color_attachments_index = vector_base_index + 1;
			const uint32_t resolve_attachments_index = vector_base_index + 2;
			const uint32_t depth_attachment_index = vector_base_index + 3;
			_convert_subpass_attachments(p_create_info->pSubpasses[i].pInputAttachments,
				p_create_info->pSubpasses[i].inputAttachmentCount,
				subpasses_attachments[input_attachments_index]);
			_convert_subpass_attachments(p_create_info->pSubpasses[i].pColorAttachments,
				p_create_info->pSubpasses[i].colorAttachmentCount,
				subpasses_attachments[color_attachments_index]);
			_convert_subpass_attachments(p_create_info->pSubpasses[i].pResolveAttachments,
				(p_create_info->pSubpasses[i].pResolveAttachments != nullptr)
					? p_create_info->pSubpasses[i].colorAttachmentCount
					: 0,
				subpasses_attachments[resolve_attachments_index]);
			_convert_subpass_attachments(p_create_info->pSubpasses[i].pDepthStencilAttachment,
				(p_create_info->pSubpasses[i].pDepthStencilAttachment != nullptr) ? 1 : 0,
				subpasses_attachments[depth_attachment_index]);

			// Ignores sType and pNext from the subpass.
			const VkSubpassDescription2& src_subpass = p_create_info->pSubpasses[i];
			VkSubpassDescription& dst_subpass = subpasses[i];
			dst_subpass.flags = src_subpass.flags;
			dst_subpass.pipelineBindPoint = src_subpass.pipelineBindPoint;
			dst_subpass.inputAttachmentCount = src_subpass.inputAttachmentCount;
			dst_subpass.pInputAttachments = subpasses_attachments[input_attachments_index].ptr();
			dst_subpass.colorAttachmentCount = src_subpass.colorAttachmentCount;
			dst_subpass.pColorAttachments = subpasses_attachments[color_attachments_index].ptr();
			dst_subpass.pResolveAttachments =
				subpasses_attachments[resolve_attachments_index].ptr();
			dst_subpass.pDepthStencilAttachment =
				subpasses_attachments[depth_attachment_index].ptr();
			dst_subpass.preserveAttachmentCount = src_subpass.preserveAttachmentCount;
			dst_subpass.pPreserveAttachments = src_subpass.pPreserveAttachments;
		}

		TightLocalVector<VkSubpassDependency> dependencies;
		dependencies.resize(p_create_info->dependencyCount);

		for (uint32_t i = 0; i < p_create_info->dependencyCount; i++) {
			// Ignores sType and pNext from the dependency, and viewMask which is currently unused.
			const VkSubpassDependency2& src_dependency = p_create_info->pDependencies[i];
			VkSubpassDependency& dst_dependency = dependencies[i];
			dst_dependency.srcSubpass = src_dependency.srcSubpass;
			dst_dependency.dstSubpass = src_dependency.dstSubpass;
			dst_dependency.srcStageMask = src_dependency.srcStageMask;
			dst_dependency.dstStageMask = src_dependency.dstStageMask;
			dst_dependency.srcAccessMask = src_dependency.srcAccessMask;
			dst_dependency.dstAccessMask = src_dependency.dstAccessMask;
			dst_dependency.dependencyFlags = src_dependency.dependencyFlags;
		}

		VkRenderPassCreateInfo create_info = {};
		create_info.sType = VK_STRUCTURE_TYPE_RENDER_PASS_CREATE_INFO;
		create_info.pNext = p_create_info->pNext;
		create_info.flags = p_create_info->flags;
		create_info.attachmentCount = attachments.size();
		create_info.pAttachments = attachments.ptr();
		create_info.subpassCount = subpasses.size();
		create_info.pSubpasses = subpasses.ptr();
		create_info.dependencyCount = dependencies.size();
		create_info.pDependencies = dependencies.ptr();
		return vkCreateRenderPass(vk_device, &create_info, p_allocator, p_render_pass);
	}
}

bool RenderingDeviceDriverVulkan::_release_image_semaphore(
	CommandQueue* p_command_queue, uint32_t p_semaphore_index, bool p_release_on_swap_chain)
{
	SwapChain* swap_chain = p_command_queue->image_semaphores_swap_chains[p_semaphore_index];
	if (swap_chain != nullptr) {
		// Clear the swap chain from the command queue's vector.
		p_command_queue->image_semaphores_swap_chains[p_semaphore_index] = nullptr;

		if (p_release_on_swap_chain) {
			// Remove the acquired semaphore from the swap chain's vectors.
			for (uint32_t i = 0; i < swap_chain->command_queues_acquired.size(); i++) {
				if (swap_chain->command_queues_acquired[i] == p_command_queue &&
					swap_chain->command_queues_acquired_semaphores[i] == p_semaphore_index) {
					swap_chain->command_queues_acquired.remove_at(i);
					swap_chain->command_queues_acquired_semaphores.remove_at(i);
					break;
				}
			}
		}

		return true;
	}

	return false;
}

bool RenderingDeviceDriverVulkan::_recreate_image_semaphore(
	CommandQueue* p_command_queue, uint32_t p_semaphore_index, bool p_release_on_swap_chain)
{
	_release_image_semaphore(p_command_queue, p_semaphore_index, p_release_on_swap_chain);

	VkSemaphore semaphore;
	VkSemaphoreCreateInfo create_info = {};
	create_info.sType = VK_STRUCTURE_TYPE_SEMAPHORE_CREATE_INFO;
	VkResult err = vkCreateSemaphore(vk_device, &create_info,
		VKC::get_allocation_callbacks(VK_OBJECT_TYPE_SEMAPHORE), &semaphore);
	ERR_FAIL_COND_V_MSG(err != VK_SUCCESS, false,
		vformat("Couldn't create Vulkan semaphore (VkResult error %d).", err));

	// Indicate the semaphore is free again and destroy the previous one before storing the new one.
	vkDestroySemaphore(vk_device, p_command_queue->image_semaphores[p_semaphore_index],
		VKC::get_allocation_callbacks(VK_OBJECT_TYPE_SEMAPHORE));

	p_command_queue->image_semaphores[p_semaphore_index] = semaphore;
	p_command_queue->free_image_semaphores.push_back(p_semaphore_index);

	return true;
}

// Debug marker extensions.
VkDebugReportObjectTypeEXT RenderingDeviceDriverVulkan::_convert_to_debug_report_objectType(
	VkObjectType p_object_type)
{
	switch (p_object_type) {
	case VK_OBJECT_TYPE_UNKNOWN:
		return VK_DEBUG_REPORT_OBJECT_TYPE_UNKNOWN_EXT;
	case VK_OBJECT_TYPE_INSTANCE:
		return VK_DEBUG_REPORT_OBJECT_TYPE_INSTANCE_EXT;
	case VK_OBJECT_TYPE_PHYSICAL_DEVICE:
		return VK_DEBUG_REPORT_OBJECT_TYPE_PHYSICAL_DEVICE_EXT;
	case VK_OBJECT_TYPE_DEVICE:
		return VK_DEBUG_REPORT_OBJECT_TYPE_DEVICE_EXT;
	case VK_OBJECT_TYPE_QUEUE:
		return VK_DEBUG_REPORT_OBJECT_TYPE_QUEUE_EXT;
	case VK_OBJECT_TYPE_SEMAPHORE:
		return VK_DEBUG_REPORT_OBJECT_TYPE_SEMAPHORE_EXT;
	case VK_OBJECT_TYPE_COMMAND_BUFFER:
		return VK_DEBUG_REPORT_OBJECT_TYPE_COMMAND_BUFFER_EXT;
	case VK_OBJECT_TYPE_FENCE:
		return VK_DEBUG_REPORT_OBJECT_TYPE_FENCE_EXT;
	case VK_OBJECT_TYPE_DEVICE_MEMORY:
		return VK_DEBUG_REPORT_OBJECT_TYPE_DEVICE_MEMORY_EXT;
	case VK_OBJECT_TYPE_BUFFER:
		return VK_DEBUG_REPORT_OBJECT_TYPE_BUFFER_EXT;
	case VK_OBJECT_TYPE_IMAGE:
		return VK_DEBUG_REPORT_OBJECT_TYPE_IMAGE_EXT;
	case VK_OBJECT_TYPE_EVENT:
		return VK_DEBUG_REPORT_OBJECT_TYPE_EVENT_EXT;
	case VK_OBJECT_TYPE_QUERY_POOL:
		return VK_DEBUG_REPORT_OBJECT_TYPE_QUERY_POOL_EXT;
	case VK_OBJECT_TYPE_BUFFER_VIEW:
		return VK_DEBUG_REPORT_OBJECT_TYPE_BUFFER_VIEW_EXT;
	case VK_OBJECT_TYPE_IMAGE_VIEW:
		return VK_DEBUG_REPORT_OBJECT_TYPE_IMAGE_VIEW_EXT;
	case VK_OBJECT_TYPE_SHADER_MODULE:
		return VK_DEBUG_REPORT_OBJECT_TYPE_SHADER_MODULE_EXT;
	case VK_OBJECT_TYPE_PIPELINE_CACHE:
		return VK_DEBUG_REPORT_OBJECT_TYPE_PIPELINE_CACHE_EXT;
	case VK_OBJECT_TYPE_PIPELINE_LAYOUT:
		return VK_DEBUG_REPORT_OBJECT_TYPE_PIPELINE_LAYOUT_EXT;
	case VK_OBJECT_TYPE_RENDER_PASS:
		return VK_DEBUG_REPORT_OBJECT_TYPE_RENDER_PASS_EXT;
	case VK_OBJECT_TYPE_PIPELINE:
		return VK_DEBUG_REPORT_OBJECT_TYPE_PIPELINE_EXT;
	case VK_OBJECT_TYPE_DESCRIPTOR_SET_LAYOUT:
		return VK_DEBUG_REPORT_OBJECT_TYPE_DESCRIPTOR_SET_LAYOUT_EXT;
	case VK_OBJECT_TYPE_SAMPLER:
		return VK_DEBUG_REPORT_OBJECT_TYPE_SAMPLER_EXT;
	case VK_OBJECT_TYPE_DESCRIPTOR_POOL:
		return VK_DEBUG_REPORT_OBJECT_TYPE_DESCRIPTOR_POOL_EXT;
	case VK_OBJECT_TYPE_DESCRIPTOR_SET:
		return VK_DEBUG_REPORT_OBJECT_TYPE_DESCRIPTOR_SET_EXT;
	case VK_OBJECT_TYPE_FRAMEBUFFER:
		return VK_DEBUG_REPORT_OBJECT_TYPE_FRAMEBUFFER_EXT;
	case VK_OBJECT_TYPE_COMMAND_POOL:
		return VK_DEBUG_REPORT_OBJECT_TYPE_COMMAND_POOL_EXT;
	case VK_OBJECT_TYPE_SAMPLER_YCBCR_CONVERSION:
		return VK_DEBUG_REPORT_OBJECT_TYPE_SAMPLER_YCBCR_CONVERSION_EXT;
	case VK_OBJECT_TYPE_DESCRIPTOR_UPDATE_TEMPLATE:
		return VK_DEBUG_REPORT_OBJECT_TYPE_DESCRIPTOR_UPDATE_TEMPLATE_EXT;
	case VK_OBJECT_TYPE_SURFACE_KHR:
		return VK_DEBUG_REPORT_OBJECT_TYPE_SURFACE_KHR_EXT;
	case VK_OBJECT_TYPE_SWAPCHAIN_KHR:
		return VK_DEBUG_REPORT_OBJECT_TYPE_SWAPCHAIN_KHR_EXT;
	case VK_OBJECT_TYPE_DISPLAY_KHR:
		return VK_DEBUG_REPORT_OBJECT_TYPE_DISPLAY_KHR_EXT;
	case VK_OBJECT_TYPE_DISPLAY_MODE_KHR:
		return VK_DEBUG_REPORT_OBJECT_TYPE_DISPLAY_MODE_KHR_EXT;
	case VK_OBJECT_TYPE_DEBUG_REPORT_CALLBACK_EXT:
		return VK_DEBUG_REPORT_OBJECT_TYPE_DEBUG_REPORT_CALLBACK_EXT_EXT;
	case VK_OBJECT_TYPE_CU_MODULE_NVX:
		return VK_DEBUG_REPORT_OBJECT_TYPE_CU_MODULE_NVX_EXT;
	case VK_OBJECT_TYPE_CU_FUNCTION_NVX:
		return VK_DEBUG_REPORT_OBJECT_TYPE_CU_FUNCTION_NVX_EXT;
	case VK_OBJECT_TYPE_ACCELERATION_STRUCTURE_KHR:
		return VK_DEBUG_REPORT_OBJECT_TYPE_ACCELERATION_STRUCTURE_KHR_EXT;
	case VK_OBJECT_TYPE_VALIDATION_CACHE_EXT:
		return VK_DEBUG_REPORT_OBJECT_TYPE_VALIDATION_CACHE_EXT_EXT;
	case VK_OBJECT_TYPE_ACCELERATION_STRUCTURE_NV:
		return VK_DEBUG_REPORT_OBJECT_TYPE_ACCELERATION_STRUCTURE_NV_EXT;
	default:
		break;
	}

	return VK_DEBUG_REPORT_OBJECT_TYPE_UNKNOWN_EXT;
}

void RenderingDeviceDriverVulkan::_set_object_name(
	VkObjectType p_object_type, uint64_t p_object_handle, String p_object_name)
{
	const RenderingContextDriverVulkan::Functions& functions = context_driver->functions_get();
	if (functions.SetDebugUtilsObjectNameEXT != nullptr) {
		CharString obj_data = p_object_name.utf8();
		VkDebugUtilsObjectNameInfoEXT name_info;
		name_info.sType = VK_STRUCTURE_TYPE_DEBUG_UTILS_OBJECT_NAME_INFO_EXT;
		name_info.pNext = nullptr;
		name_info.objectType = p_object_type;
		name_info.objectHandle = p_object_handle;
		name_info.pObjectName = obj_data.get_data();
		functions.SetDebugUtilsObjectNameEXT(vk_device, &name_info);
	}
	else if (functions.DebugMarkerSetObjectNameEXT != nullptr) {
		// Debug marker extensions.
		CharString obj_data = p_object_name.utf8();
		VkDebugMarkerObjectNameInfoEXT name_info;
		name_info.sType = VK_STRUCTURE_TYPE_DEBUG_UTILS_OBJECT_NAME_INFO_EXT;
		name_info.pNext = nullptr;
		name_info.objectType = _convert_to_debug_report_objectType(p_object_type);
		name_info.object = p_object_handle;
		name_info.pObjectName = obj_data.get_data();
		functions.DebugMarkerSetObjectNameEXT(vk_device, &name_info);
	}
}

Error RenderingDeviceDriverVulkan::initialize(uint32_t p_device_index, uint32_t p_frame_count)
{
	context_device = context_driver->device_get(p_device_index);
	physical_device = context_driver->physical_device_get(p_device_index);
	frame_count = p_frame_count;

	// Copy the queue family properties the context already retrieved.
	uint32_t queue_family_count = context_driver->queue_family_get_count(p_device_index);
	queue_family_properties.resize(queue_family_count);
	for (uint32_t i = 0; i < queue_family_count; i++) {
		queue_family_properties[i] = context_driver->queue_family_get(p_device_index, i);
	}

	Error err = _initialize_device_extensions();
	ERR_FAIL_COND_V_MSG(err != OK, err,
		"Couldn't initialize Vulkan device extensions. This may be caused by an incompatible or "
		"outdated graphics driver.");

	_get_device_properties();

	err = _check_device_features();
	ERR_FAIL_COND_V_MSG(err != OK, err,
		"Couldn't initialize Vulkan device features. This may be caused by an incompatible or "
		"outdated graphics driver.");

	err = _check_device_capabilities();
	ERR_FAIL_COND_V_MSG(err != OK, err,
		"Couldn't initialize Vulkan device capabilities. This may be caused by an incompatible or "
		"outdated graphics driver.");

	LocalVector<VkDeviceQueueCreateInfo> queue_create_info;
	err = _add_queue_create_info(queue_create_info);
	ERR_FAIL_COND_V_MSG(err != OK, err,
		"Couldn't initialize Vulkan device queue. This may be caused by an incompatible or "
		"outdated graphics driver.");

	err = _initialize_device(queue_create_info);
	ERR_FAIL_COND_V_MSG(err != OK, err,
		"Couldn't initialize Vulkan device. This may be caused by an incompatible or outdated "
		"graphics driver.");

	err = _initialize_allocator();
	ERR_FAIL_COND_V_MSG(err != OK, err,
		"Couldn't initialize Vulkan memory allocator. This may be caused by an incompatible or "
		"outdated graphics driver.");

	err = _initialize_pipeline_cache();
	ERR_FAIL_COND_V_MSG(err != OK, err,
		"Couldn't initialize Vulkan pipeline cache. This may be caused by an incompatible or "
		"outdated graphics driver.");

#if defined(DEBUG_ENABLED) || defined(DEV_ENABLED)
	breadcrumb_buffer = buffer_create(2u * sizeof(uint32_t) * BREADCRUMB_BUFFER_ENTRIES,
		BufferUsageBits::BUFFER_USAGE_TRANSFER_TO_BIT,
		MemoryAllocationType::MEMORY_ALLOCATION_TYPE_CPU, UINT64_MAX);
#endif

#if defined(SWAPPY_FRAME_PACING_ENABLED)
	swappy_frame_pacer_enable =
		GLOBAL_GET("display/window/frame_pacing/android/enable_frame_pacing");
	swappy_mode = GLOBAL_GET("display/window/frame_pacing/android/swappy_mode");

	if (VulkanHooks::is_bound()) {
		// Hooks control device creation & possibly presentation
		// (e.g. OpenXR) thus it's too risky to use Swappy.
		swappy_frame_pacer_enable = false;
		OS::print(
			"VulkanHooks detected (e.g. OpenXR): Force-disabling Swappy Frame Pacing.\n");
	}
#endif

	shader_container_format.set_debug_info_enabled(
		Engine::is_generate_spirv_debug_info_enabled());

#if RECORD_PIPELINE_STATISTICS
	pipeline_statistics.file_access =
		FileAccess::open(RECORD_PIPELINE_STATISTICS_PATH, FileAccess::WRITE);
	ERR_FAIL_NULL_V_MSG(pipeline_statistics.file_access, ERR_CANT_CREATE,
		"Couldn't write Vulkan pipeline statistics file.");

	pipeline_statistics.file_access->store_csv_line(
		{"name", "hash", "stage", "spec", "glslang", "re-spirv", "time"});
	pipeline_statistics.file_access->flush();
#endif

	return OK;
}

static const uint32_t SMALL_ALLOCATION_MAX_SIZE = 4096;

VmaPool RenderingDeviceDriverVulkan::_find_or_create_small_allocs_pool(uint32_t p_mem_type_index)
{
	if (small_allocs_pools.has(p_mem_type_index)) {
		return small_allocs_pools[p_mem_type_index];
	}

	print_verbose(
		"Creating VMA small objects pool for memory type index " + itos(p_mem_type_index));

	VmaPoolCreateInfo pci = {};
	pci.memoryTypeIndex = p_mem_type_index;
	pci.flags = 0;
	pci.blockSize = 0;
	pci.minBlockCount = 0;
	pci.maxBlockCount = SIZE_MAX;
	pci.priority = 0.5f;
	pci.minAllocationAlignment = 0;
	pci.pMemoryAllocateNext = nullptr;
	VmaPool pool = VK_NULL_HANDLE;
	VkResult res = vmaCreatePool(allocator, &pci, &pool);
	small_allocs_pools[p_mem_type_index] =
		pool; // Don't try to create it again if failed the first time.
	ERR_FAIL_COND_V_MSG(res, pool,
		vformat("Couldn't create Vulkan memory allocator pool (VkResult error %d)", res));

	return pool;
}

// RDD::BufferUsageBits == VkBufferUsageFlagBits.
static_assert(
	ENUM_MEMBERS_EQUAL(RDD::BUFFER_USAGE_TRANSFER_FROM_BIT, VK_BUFFER_USAGE_TRANSFER_SRC_BIT));
static_assert(
	ENUM_MEMBERS_EQUAL(RDD::BUFFER_USAGE_TRANSFER_TO_BIT, VK_BUFFER_USAGE_TRANSFER_DST_BIT));
static_assert(
	ENUM_MEMBERS_EQUAL(RDD::BUFFER_USAGE_TEXEL_BIT, VK_BUFFER_USAGE_UNIFORM_TEXEL_BUFFER_BIT));
static_assert(
	ENUM_MEMBERS_EQUAL(RDD::BUFFER_USAGE_UNIFORM_BIT, VK_BUFFER_USAGE_UNIFORM_BUFFER_BIT));
static_assert(
	ENUM_MEMBERS_EQUAL(RDD::BUFFER_USAGE_STORAGE_BIT, VK_BUFFER_USAGE_STORAGE_BUFFER_BIT));
static_assert(ENUM_MEMBERS_EQUAL(RDD::BUFFER_USAGE_INDEX_BIT, VK_BUFFER_USAGE_INDEX_BUFFER_BIT));
static_assert(ENUM_MEMBERS_EQUAL(RDD::BUFFER_USAGE_VERTEX_BIT, VK_BUFFER_USAGE_VERTEX_BUFFER_BIT));
static_assert(
	ENUM_MEMBERS_EQUAL(RDD::BUFFER_USAGE_INDIRECT_BIT, VK_BUFFER_USAGE_INDIRECT_BUFFER_BIT));
static_assert(ENUM_MEMBERS_EQUAL(
	RDD::BUFFER_USAGE_SHADER_BINDING_TABLE_BIT, VK_BUFFER_USAGE_SHADER_BINDING_TABLE_BIT_KHR));
static_assert(ENUM_MEMBERS_EQUAL(
	RDD::BUFFER_USAGE_DEVICE_ADDRESS_BIT, VK_BUFFER_USAGE_SHADER_DEVICE_ADDRESS_BIT));
static_assert(ENUM_MEMBERS_EQUAL(RDD::BUFFER_USAGE_ACCELERATION_STRUCTURE_BUILD_INPUT_READ_ONLY_BIT,
	VK_BUFFER_USAGE_ACCELERATION_STRUCTURE_BUILD_INPUT_READ_ONLY_BIT_KHR));
static_assert(ENUM_MEMBERS_EQUAL(RDD::BUFFER_USAGE_ACCELERATION_STRUCTURE_STORAGE_BIT,
	VK_BUFFER_USAGE_ACCELERATION_STRUCTURE_STORAGE_BIT_KHR));

RDD::BufferID RenderingDeviceDriverVulkan::buffer_create(uint64_t p_size,
	uint32_t p_usage, MemoryAllocationType p_allocation_type,
	uint64_t p_frames_drawn)
{
	uint32_t alignment = 16u; // 16 bytes is reasonable.
	if (Utils::has_flag(p_usage, BUFFER_USAGE_UNIFORM_BIT)) {
		// Some GPUs (e.g. NVIDIA) have absurdly high alignments, like 256 bytes.
		alignment =
			MAX(alignment, physical_device_properties.limits.minUniformBufferOffsetAlignment);
	}
	if (Utils::has_flag(p_usage, BUFFER_USAGE_STORAGE_BIT)) {
		// This shouldn't be a problem since it's often <= 16 bytes. But do it just in case.
		alignment =
			MAX(alignment, physical_device_properties.limits.minStorageBufferOffsetAlignment);
	}
	// Align the size. This is specially important for BUFFER_USAGE_DYNAMIC_PERSISTENT_BIT buffers.
	// For the rest, it should work thanks to VMA taking care of the details. But still align just
	// in case.
	p_size = STEPIFY(p_size, alignment);

	const size_t original_size = p_size;
	if (Utils::has_flag(p_usage, BUFFER_USAGE_DYNAMIC_PERSISTENT_BIT)) {
		p_size = p_size * frame_count;
	}
	VkBufferCreateInfo create_info = {};
	create_info.sType = VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO;
	create_info.size = p_size;
	uint32_t usage = p_usage;
	usage &= ~(BUFFER_USAGE_DYNAMIC_PERSISTENT_BIT);
	create_info.usage = VkBufferUsageFlags(usage);
	create_info.sharingMode = VK_SHARING_MODE_EXCLUSIVE;

	VmaMemoryUsage vma_usage = VMA_MEMORY_USAGE_UNKNOWN;
	uint32_t vma_flags_to_remove = 0;

	VmaAllocationCreateInfo alloc_create_info = {};
	switch (p_allocation_type) {
	case MEMORY_ALLOCATION_TYPE_CPU: {
		bool is_src = Utils::has_flag(p_usage, BUFFER_USAGE_TRANSFER_FROM_BIT);
		bool is_dst = Utils::has_flag(p_usage, BUFFER_USAGE_TRANSFER_TO_BIT);
		if (is_src && !is_dst) {
			// Looks like a staging buffer: CPU maps, writes sequentially, then GPU copies to VRAM.
			alloc_create_info.flags = VMA_ALLOCATION_CREATE_HOST_ACCESS_SEQUENTIAL_WRITE_BIT;
			alloc_create_info.preferredFlags = Utils::set_flag(alloc_create_info.preferredFlags, VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT);
			vma_flags_to_remove = Utils::set_flag(vma_flags_to_remove, VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT);
		}
		if (is_dst && !is_src) {
			// Looks like a readback buffer: GPU copies from VRAM, then CPU maps and reads.
			alloc_create_info.flags = VMA_ALLOCATION_CREATE_HOST_ACCESS_RANDOM_BIT;
			alloc_create_info.preferredFlags = Utils::set_flag(alloc_create_info.preferredFlags, VK_MEMORY_PROPERTY_HOST_CACHED_BIT);
			vma_flags_to_remove = Utils::set_flag(vma_flags_to_remove, VK_MEMORY_PROPERTY_HOST_CACHED_BIT);
		}
		vma_usage = VMA_MEMORY_USAGE_AUTO_PREFER_HOST;
		alloc_create_info.requiredFlags =
			(VK_MEMORY_PROPERTY_HOST_COHERENT_BIT | VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT);
	} break;
	case MEMORY_ALLOCATION_TYPE_GPU: {
		vma_usage = VMA_MEMORY_USAGE_AUTO_PREFER_DEVICE;
		if (!Engine::is_extra_gpu_memory_tracking_enabled()) {
			// We must set it right now or else vmaFindMemoryTypeIndexForBufferInfo will use wrong
			// parameters.
			alloc_create_info.usage = vma_usage;
		}
		if (Utils::has_flag(p_usage, BUFFER_USAGE_DYNAMIC_PERSISTENT_BIT)) {
			alloc_create_info.flags = VMA_ALLOCATION_CREATE_HOST_ACCESS_SEQUENTIAL_WRITE_BIT;
		}
		alloc_create_info.preferredFlags = VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT;
		if (p_size <= SMALL_ALLOCATION_MAX_SIZE) {
			uint32_t mem_type_index = 0;
			vmaFindMemoryTypeIndexForBufferInfo(
				allocator, &create_info, &alloc_create_info, &mem_type_index);
			alloc_create_info.pool = _find_or_create_small_allocs_pool(mem_type_index);
		}
	} break;
	}

	VkBuffer vk_buffer = VK_NULL_HANDLE;
	VmaAllocation allocation = nullptr;
	VmaAllocationInfo alloc_info = {};

	if (!Engine::is_extra_gpu_memory_tracking_enabled()) {
		alloc_create_info.preferredFlags &= ~vma_flags_to_remove;
		alloc_create_info.usage = vma_usage;
		VkResult err = vmaCreateBuffer(
			allocator, &create_info, &alloc_create_info, &vk_buffer, &allocation, &alloc_info);
		ERR_FAIL_COND_V_MSG(err, BufferID(),
			vformat("Can't create buffer of size: %d (VkResult error %d).", p_size, err));
	}
	else {
		VkResult err = vkCreateBuffer(vk_device, &create_info,
			VKC::get_allocation_callbacks(VK_OBJECT_TYPE_BUFFER), &vk_buffer);
		ERR_FAIL_COND_V_MSG(err, BufferID(),
			vformat("Can't create buffer of size: %d (VkResult error %d).", p_size, err));
		err = vmaAllocateMemoryForBuffer(
			allocator, vk_buffer, &alloc_create_info, &allocation, &alloc_info);
		ERR_FAIL_COND_V_MSG(err, BufferID(),
			vformat(
				"Can't allocate memory for buffer of size: %d (VkResult error %d).", p_size, err));
		err = vmaBindBufferMemory2(allocator, allocation, 0, vk_buffer, nullptr);
		ERR_FAIL_COND_V_MSG(err, BufferID(),
			vformat("Can't bind memory to buffer of size: %d (VkResult error %d).", p_size, err));
	}

	// Bookkeep.
	BufferInfo* buf_info;
	if (Utils::has_flag(p_usage, BUFFER_USAGE_DYNAMIC_PERSISTENT_BIT)) {
		void* persistent_ptr = nullptr;
		VkResult err = vmaMapMemory(allocator, allocation, &persistent_ptr);
		ERR_FAIL_COND_V_MSG(err, BufferID(),
			vformat("Couldn't map Vulkan buffer memory (VkResult error %d).", err));

		BufferDynamicInfo* dyn_buffer =
			VersatileResource::allocate<BufferDynamicInfo>(resources_allocator);
		buf_info = dyn_buffer;
#ifdef DEBUG_ENABLED
		dyn_buffer->last_frame_mapped = p_frames_drawn - 1ul;
#endif
		dyn_buffer->frame_idx = 0u;
		dyn_buffer->persistent_ptr = (uint8_t*)persistent_ptr;
	}
	else {
		buf_info = VersatileResource::allocate<BufferInfo>(resources_allocator);
	}
	buf_info->vk_buffer = vk_buffer;
	buf_info->allocation.handle = allocation;
	buf_info->allocation.size = alloc_info.size;
	buf_info->size = original_size;

	return BufferID(buf_info);
}

bool RenderingDeviceDriverVulkan::buffer_set_texel_format(BufferID p_buffer, RDC::DataFormat p_format)
{
	BufferInfo* buf_info = (BufferInfo*)p_buffer.id;

	DEV_ASSERT(!buf_info->vk_view);

	VkBufferViewCreateInfo view_create_info = {};
	view_create_info.sType = VK_STRUCTURE_TYPE_BUFFER_VIEW_CREATE_INFO;
	view_create_info.buffer = buf_info->vk_buffer;
	view_create_info.format = RD_TO_VK_FORMAT[p_format];
	view_create_info.range = buf_info->allocation.size;

	VkResult res = vkCreateBufferView(vk_device, &view_create_info,
		VKC::get_allocation_callbacks(VK_OBJECT_TYPE_BUFFER_VIEW), &buf_info->vk_view);
	ERR_FAIL_COND_V_MSG(
		res, false, vformat("Couldn't create Vulkan buffer view (VkResult error %d).", res));

	return true;
}

void RenderingDeviceDriverVulkan::buffer_free(BufferID p_buffer)
{
	BufferInfo* buf_info = (BufferInfo*)p_buffer.id;
	if (buf_info->vk_view) {
		vkDestroyBufferView(vk_device, buf_info->vk_view,
			VKC::get_allocation_callbacks(VK_OBJECT_TYPE_BUFFER_VIEW));
	}

	if (buf_info->is_dynamic()) {
		vmaUnmapMemory(allocator, buf_info->allocation.handle);
	}

	if (!Engine::is_extra_gpu_memory_tracking_enabled()) {
		vmaDestroyBuffer(allocator, buf_info->vk_buffer, buf_info->allocation.handle);
	}
	else {
		vkDestroyBuffer(
			vk_device, buf_info->vk_buffer, VKC::get_allocation_callbacks(VK_OBJECT_TYPE_BUFFER));
		vmaFreeMemory(allocator, buf_info->allocation.handle);
	}

	if (buf_info->is_dynamic()) {
		VersatileResource::free(resources_allocator, (BufferDynamicInfo*)buf_info);
	}
	else {
		VersatileResource::free(resources_allocator, buf_info);
	}
}

uint64_t RenderingDeviceDriverVulkan::buffer_get_allocation_size(BufferID p_buffer)
{
	const BufferInfo* buf_info = (const BufferInfo*)p_buffer.id;
	return buf_info->allocation.size;
}

uint8_t* RenderingDeviceDriverVulkan::buffer_map(BufferID p_buffer)
{
	const BufferInfo* buf_info = (const BufferInfo*)p_buffer.id;
	ERR_FAIL_COND_V_MSG(buf_info->is_dynamic(), nullptr,
		"Buffer must NOT have BUFFER_USAGE_DYNAMIC_PERSISTENT_BIT. Use "
		"buffer_persistent_map_advance() instead.");
	void* data_ptr = nullptr;
	VkResult err = vmaMapMemory(allocator, buf_info->allocation.handle, &data_ptr);
	ERR_FAIL_COND_V_MSG(
		err, nullptr, vformat("Couldn't map buffer memory (VkResult error %d).", err));
	return (uint8_t*)data_ptr;
}

void RenderingDeviceDriverVulkan::buffer_unmap(BufferID p_buffer)
{
	const BufferInfo* buf_info = (const BufferInfo*)p_buffer.id;
	vmaUnmapMemory(allocator, buf_info->allocation.handle);
}

uint8_t* RenderingDeviceDriverVulkan::buffer_persistent_map_advance(
	BufferID p_buffer, uint64_t p_frames_drawn)
{
	BufferDynamicInfo* buf_info = (BufferDynamicInfo*)p_buffer.id;
	ERR_FAIL_COND_V_MSG(!buf_info->is_dynamic(), nullptr,
		"Buffer must have BUFFER_USAGE_DYNAMIC_PERSISTENT_BIT. Use buffer_map() instead.");
#ifdef DEBUG_ENABLED
	ERR_FAIL_COND_V_MSG(buf_info->last_frame_mapped == p_frames_drawn, nullptr,
		"Buffers with BUFFER_USAGE_DYNAMIC_PERSISTENT_BIT must only be mapped once per frame. "
		"Otherwise there could be race conditions with the GPU. Amalgamate all data uploading into "
		"one map(), use an extra buffer, or remove the bit.");
	buf_info->last_frame_mapped = p_frames_drawn;
#endif
	buf_info->frame_idx = (buf_info->frame_idx + 1u) % frame_count;
	return buf_info->persistent_ptr + buf_info->frame_idx * buf_info->size;
}

uint64_t RenderingDeviceDriverVulkan::buffer_get_dynamic_offsets(Span<BufferID> p_buffers)
{
	uint64_t mask = 0u;
	uint64_t shift = 0u;

	for (const BufferID& buf : p_buffers) {
		const BufferInfo* buf_info = (const BufferInfo*)buf.id;
		if (!buf_info->is_dynamic()) {
			continue;
		}
		mask = Utils::set_flag(mask, (buf_info->frame_idx << shift));
		// We can encode the frame index in 2 bits since frame_count won't be > 4.
		shift += 2UL;
	}

	return mask;
}

void RenderingDeviceDriverVulkan::buffer_flush(BufferID p_buffer)
{
	BufferDynamicInfo* buf_info = (BufferDynamicInfo*)p_buffer.id;

	VkMemoryPropertyFlags mem_props_flags;
	vmaGetAllocationMemoryProperties(allocator, buf_info->allocation.handle, &mem_props_flags);

	const bool needs_flushing = !(mem_props_flags & VK_MEMORY_PROPERTY_HOST_COHERENT_BIT);

	if (needs_flushing) {
		if (buf_info->is_dynamic()) {
			pending_flushes.allocations.push_back(buf_info->allocation.handle);
			pending_flushes.offsets.push_back(buf_info->frame_idx * buf_info->size);
			pending_flushes.sizes.push_back(buf_info->size);
		}
		else {
			pending_flushes.allocations.push_back(buf_info->allocation.handle);
			pending_flushes.offsets.push_back(0u);
			pending_flushes.sizes.push_back(VK_WHOLE_SIZE);
		}
	}
}

uint64_t RenderingDeviceDriverVulkan::buffer_get_device_address(BufferID p_buffer)
{
	const BufferInfo* buf_info = (const BufferInfo*)p_buffer.id;
	VkBufferDeviceAddressInfo address_info = {};
	address_info.sType = VK_STRUCTURE_TYPE_BUFFER_DEVICE_ADDRESS_INFO;
	address_info.pNext = nullptr;
	address_info.buffer = buf_info->vk_buffer;
	return vkGetBufferDeviceAddress(vk_device, &address_info);
}

static const VkImageType RD_TEX_TYPE_TO_VK_IMG_TYPE[RDC::TEXTURE_TYPE_MAX] = {
	VK_IMAGE_TYPE_1D,
	VK_IMAGE_TYPE_2D,
	VK_IMAGE_TYPE_3D,
	VK_IMAGE_TYPE_2D,
	VK_IMAGE_TYPE_1D,
	VK_IMAGE_TYPE_2D,
	VK_IMAGE_TYPE_2D,
};

static const VkSampleCountFlagBits RD_TO_VK_SAMPLE_COUNT[RDC::TEXTURE_SAMPLES_MAX] = {
	VK_SAMPLE_COUNT_1_BIT,
	VK_SAMPLE_COUNT_2_BIT,
	VK_SAMPLE_COUNT_4_BIT,
	VK_SAMPLE_COUNT_8_BIT,
	VK_SAMPLE_COUNT_16_BIT,
	VK_SAMPLE_COUNT_32_BIT,
	VK_SAMPLE_COUNT_64_BIT,
};

// RDD::TextureType == VkImageViewType.
static_assert(ENUM_MEMBERS_EQUAL(RDC::TEXTURE_TYPE_1D, VK_IMAGE_VIEW_TYPE_1D));
static_assert(ENUM_MEMBERS_EQUAL(RDC::TEXTURE_TYPE_2D, VK_IMAGE_VIEW_TYPE_2D));
static_assert(ENUM_MEMBERS_EQUAL(RDC::TEXTURE_TYPE_3D, VK_IMAGE_VIEW_TYPE_3D));
static_assert(ENUM_MEMBERS_EQUAL(RDC::TEXTURE_TYPE_CUBE, VK_IMAGE_VIEW_TYPE_CUBE));
static_assert(ENUM_MEMBERS_EQUAL(RDC::TEXTURE_TYPE_1D_ARRAY, VK_IMAGE_VIEW_TYPE_1D_ARRAY));
static_assert(ENUM_MEMBERS_EQUAL(RDC::TEXTURE_TYPE_2D_ARRAY, VK_IMAGE_VIEW_TYPE_2D_ARRAY));
static_assert(ENUM_MEMBERS_EQUAL(RDC::TEXTURE_TYPE_CUBE_ARRAY, VK_IMAGE_VIEW_TYPE_CUBE_ARRAY));

// RDC::TextureSwizzle == VkComponentSwizzle.
static_assert(ENUM_MEMBERS_EQUAL(RDC::TEXTURE_SWIZZLE_IDENTITY, VK_COMPONENT_SWIZZLE_IDENTITY));
static_assert(ENUM_MEMBERS_EQUAL(RDC::TEXTURE_SWIZZLE_ZERO, VK_COMPONENT_SWIZZLE_ZERO));
static_assert(ENUM_MEMBERS_EQUAL(RDC::TEXTURE_SWIZZLE_ONE, VK_COMPONENT_SWIZZLE_ONE));
static_assert(ENUM_MEMBERS_EQUAL(RDC::TEXTURE_SWIZZLE_R, VK_COMPONENT_SWIZZLE_R));
static_assert(ENUM_MEMBERS_EQUAL(RDC::TEXTURE_SWIZZLE_G, VK_COMPONENT_SWIZZLE_G));
static_assert(ENUM_MEMBERS_EQUAL(RDC::TEXTURE_SWIZZLE_B, VK_COMPONENT_SWIZZLE_B));
static_assert(ENUM_MEMBERS_EQUAL(RDC::TEXTURE_SWIZZLE_A, VK_COMPONENT_SWIZZLE_A));

// RDC::TextureAspectBits == VkImageAspectFlagBits.
static_assert(ENUM_MEMBERS_EQUAL(RDD::TEXTURE_ASPECT_COLOR_BIT, VK_IMAGE_ASPECT_COLOR_BIT));
static_assert(ENUM_MEMBERS_EQUAL(RDD::TEXTURE_ASPECT_DEPTH_BIT, VK_IMAGE_ASPECT_DEPTH_BIT));
static_assert(ENUM_MEMBERS_EQUAL(RDD::TEXTURE_ASPECT_STENCIL_BIT, VK_IMAGE_ASPECT_STENCIL_BIT));

VkSampleCountFlagBits RenderingDeviceDriverVulkan::_ensure_supported_sample_count(
	RDC::TextureSamples p_requested_sample_count)
{
	VkSampleCountFlags sample_count_flags =
		(physical_device_properties.limits.framebufferColorSampleCounts &
			physical_device_properties.limits.framebufferDepthSampleCounts);

	if ((sample_count_flags & RD_TO_VK_SAMPLE_COUNT[p_requested_sample_count])) {
		// The requested sample count is supported.
		return RD_TO_VK_SAMPLE_COUNT[p_requested_sample_count];
	}
	else {
		// Find the closest lower supported sample count.
		VkSampleCountFlagBits sample_count = RD_TO_VK_SAMPLE_COUNT[p_requested_sample_count];
		while (sample_count > VK_SAMPLE_COUNT_1_BIT) {
			if (sample_count_flags & sample_count) {
				return sample_count;
			}
			sample_count = (VkSampleCountFlagBits)(sample_count >> 1);
		}
	}
	return VK_SAMPLE_COUNT_1_BIT;
}

RDD::TextureID RenderingDeviceDriverVulkan::texture_create(
	const RDC::TextureFormat& p_format, const TextureView& p_view)
{
	VkImageCreateInfo create_info = {};
	create_info.sType = VK_STRUCTURE_TYPE_IMAGE_CREATE_INFO;

	if (p_format.shareable_formats.size()) {
		create_info.flags = Utils::set_flag(create_info.flags, VK_IMAGE_CREATE_MUTABLE_FORMAT_BIT);

		if (enabled_device_extension_names.has(VK_KHR_IMAGE_FORMAT_LIST_EXTENSION_NAME)) {
			VkFormat* vk_allowed_formats =
				ALLOCA_ARRAY(VkFormat, p_format.shareable_formats.size());
			for (int i = 0; i < p_format.shareable_formats.size(); i++) {
				vk_allowed_formats[i] = RD_TO_VK_FORMAT[p_format.shareable_formats[i]];
			}

			VkImageFormatListCreateInfoKHR* format_list_create_info =
				ALLOCA_SINGLE(VkImageFormatListCreateInfoKHR);
			*format_list_create_info = {};
			format_list_create_info->sType = VK_STRUCTURE_TYPE_IMAGE_FORMAT_LIST_CREATE_INFO_KHR;
			format_list_create_info->viewFormatCount = p_format.shareable_formats.size();
			format_list_create_info->pViewFormats = vk_allowed_formats;

			create_info.pNext = format_list_create_info;
		}
	}

	if (p_format.texture_type == RDC::TEXTURE_TYPE_CUBE ||
		p_format.texture_type == RDC::TEXTURE_TYPE_CUBE_ARRAY) {
		create_info.flags = Utils::set_flag(create_info.flags, VK_IMAGE_CREATE_CUBE_COMPATIBLE_BIT);
	}

	bool use_subsampled_images =
		VulkanHooks::is_bound() && VulkanHooks::use_subsampled_images();
	if (fdm_capabilities.attachment_supported && use_subsampled_images && p_format.is_subsampled &&
		(p_format.usage_bits &
			(RDC::TEXTURE_USAGE_COLOR_ATTACHMENT_BIT | RDC::TEXTURE_USAGE_DEPTH_STENCIL_ATTACHMENT_BIT |
				RDC::TEXTURE_USAGE_INPUT_ATTACHMENT_BIT | RDC::TEXTURE_USAGE_DEPTH_RESOLVE_ATTACHMENT_BIT))) {
		create_info.flags = Utils::set_flag(create_info.flags, VK_IMAGE_CREATE_SUBSAMPLED_BIT_EXT);
	}

	if (fdm_capabilities.offset_supported &&
		(p_format.usage_bits &
			(RDC::TEXTURE_USAGE_COLOR_ATTACHMENT_BIT | RDC::TEXTURE_USAGE_DEPTH_STENCIL_ATTACHMENT_BIT |
				RDC::TEXTURE_USAGE_INPUT_ATTACHMENT_BIT | RDC::TEXTURE_USAGE_DEPTH_RESOLVE_ATTACHMENT_BIT |
				RDC::TEXTURE_USAGE_VRS_ATTACHMENT_BIT))) {
		create_info.flags = Utils::set_flag(create_info.flags, VK_IMAGE_CREATE_FRAGMENT_DENSITY_MAP_OFFSET_BIT_QCOM);
	}

	create_info.imageType = RD_TEX_TYPE_TO_VK_IMG_TYPE[p_format.texture_type];

	create_info.format = RD_TO_VK_FORMAT[p_format.format];

	create_info.extent.width = p_format.width;
	create_info.extent.height = p_format.height;
	create_info.extent.depth = p_format.depth;

	create_info.mipLevels = p_format.mipmaps;
	create_info.arrayLayers = p_format.array_layers;

	create_info.samples = _ensure_supported_sample_count(p_format.samples);
	create_info.tiling = (p_format.usage_bits & RDC::TEXTURE_USAGE_CPU_READ_BIT)
							 ? VK_IMAGE_TILING_LINEAR
							 : VK_IMAGE_TILING_OPTIMAL;

	// Usage.
	if ((p_format.usage_bits & RDC::TEXTURE_USAGE_SAMPLING_BIT)) {
		create_info.usage = Utils::set_flag(create_info.usage, VK_IMAGE_USAGE_SAMPLED_BIT);
	}
	if ((p_format.usage_bits & RDC::TEXTURE_USAGE_STORAGE_BIT)) {
		create_info.usage = Utils::set_flag(create_info.usage, VK_IMAGE_USAGE_STORAGE_BIT);
	}
	if ((p_format.usage_bits & RDC::TEXTURE_USAGE_COLOR_ATTACHMENT_BIT)) {
		create_info.usage = Utils::set_flag(create_info.usage, VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT);
	}
	if ((p_format.usage_bits & (RDC::TEXTURE_USAGE_DEPTH_STENCIL_ATTACHMENT_BIT |
								   RDC::TEXTURE_USAGE_DEPTH_RESOLVE_ATTACHMENT_BIT))) {
		create_info.usage = Utils::set_flag(create_info.usage, VK_IMAGE_USAGE_DEPTH_STENCIL_ATTACHMENT_BIT);
	}
	if ((p_format.usage_bits & RDC::TEXTURE_USAGE_INPUT_ATTACHMENT_BIT)) {
		create_info.usage = Utils::set_flag(create_info.usage, VK_IMAGE_USAGE_INPUT_ATTACHMENT_BIT);
	}
	if ((p_format.usage_bits & RDC::TEXTURE_USAGE_VRS_ATTACHMENT_BIT) &&
		(p_format.usage_bits & TEXTURE_USAGE_VRS_FRAGMENT_SHADING_RATE_BIT)) {
		create_info.usage = Utils::set_flag(create_info.usage, VK_IMAGE_USAGE_FRAGMENT_SHADING_RATE_ATTACHMENT_BIT_KHR);
	}
	if ((p_format.usage_bits & RDC::TEXTURE_USAGE_VRS_ATTACHMENT_BIT) &&
		(p_format.usage_bits & TEXTURE_USAGE_VRS_FRAGMENT_DENSITY_MAP_BIT)) {
		create_info.usage = Utils::set_flag(create_info.usage, VK_IMAGE_USAGE_FRAGMENT_DENSITY_MAP_BIT_EXT);
	}
	if ((p_format.usage_bits & RDC::TEXTURE_USAGE_CAN_UPDATE_BIT)) {
		create_info.usage = Utils::set_flag(create_info.usage, VK_IMAGE_USAGE_TRANSFER_DST_BIT);
	}
	if ((p_format.usage_bits & RDC::TEXTURE_USAGE_CAN_COPY_FROM_BIT)) {
		create_info.usage = Utils::set_flag(create_info.usage, VK_IMAGE_USAGE_TRANSFER_SRC_BIT);
	}
	if ((p_format.usage_bits & RDC::TEXTURE_USAGE_CAN_COPY_TO_BIT)) {
		create_info.usage = Utils::set_flag(create_info.usage, VK_IMAGE_USAGE_TRANSFER_DST_BIT);
	}

	create_info.sharingMode = VK_SHARING_MODE_EXCLUSIVE;
	create_info.initialLayout = VK_IMAGE_LAYOUT_UNDEFINED;

	// Allocate memory.

	uint32_t width = 0, height = 0;
	uint32_t image_size = RDC::get_image_format_required_size(p_format.format, p_format.width,
		p_format.height, p_format.depth, p_format.mipmaps, &width, &height);

	VmaAllocationCreateInfo alloc_create_info = {};
	alloc_create_info.flags = (p_format.usage_bits & RDC::TEXTURE_USAGE_CPU_READ_BIT)
								  ? VMA_ALLOCATION_CREATE_HOST_ACCESS_RANDOM_BIT
								  : 0;

	if (p_format.usage_bits & RDC::TEXTURE_USAGE_TRANSIENT_BIT) {
		uint32_t memory_type_index = 0;
		VmaAllocationCreateInfo lazy_memory_requirements = alloc_create_info;
		lazy_memory_requirements.usage = VMA_MEMORY_USAGE_GPU_LAZILY_ALLOCATED;
		VkResult result = vmaFindMemoryTypeIndex(
			allocator, UINT32_MAX, &lazy_memory_requirements, &memory_type_index);
		if (VK_SUCCESS == result) {
			alloc_create_info = lazy_memory_requirements;
			create_info.usage = Utils::set_flag(create_info.usage, VK_IMAGE_USAGE_TRANSIENT_ATTACHMENT_BIT);
			// VUID-VkImageCreateInfo-usage-00963 :
			// If usage includes VK_IMAGE_USAGE_TRANSIENT_ATTACHMENT_BIT,
			// then bits other than VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT,
			// VK_IMAGE_USAGE_DEPTH_STENCIL_ATTACHMENT_BIT, and VK_IMAGE_USAGE_INPUT_ATTACHMENT_BIT
			// must not be set.
			create_info.usage &=
				(VK_IMAGE_USAGE_TRANSIENT_ATTACHMENT_BIT | VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT |
					VK_IMAGE_USAGE_DEPTH_STENCIL_ATTACHMENT_BIT |
					VK_IMAGE_USAGE_INPUT_ATTACHMENT_BIT);
		}
		else {
			alloc_create_info.preferredFlags = VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT;
		}
	}
	else if (p_format.usage_bits & RDC::TEXTURE_USAGE_CPU_READ_BIT) {
		alloc_create_info.preferredFlags = VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT;
	}
	else {
		alloc_create_info.preferredFlags = VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT;
	}

	if (image_size <= SMALL_ALLOCATION_MAX_SIZE) {
		uint32_t mem_type_index = 0;
		vmaFindMemoryTypeIndexForImageInfo(
			allocator, &create_info, &alloc_create_info, &mem_type_index);
		alloc_create_info.pool = _find_or_create_small_allocs_pool(mem_type_index);
	}

	// Create.

	VkImage vk_image = VK_NULL_HANDLE;
	VmaAllocation allocation = nullptr;
	VmaAllocationInfo alloc_info = {};

	if (!Engine::is_extra_gpu_memory_tracking_enabled()) {
		alloc_create_info.usage = VMA_MEMORY_USAGE_AUTO_PREFER_DEVICE;
		VkResult err = vmaCreateImage(
			allocator, &create_info, &alloc_create_info, &vk_image, &allocation, &alloc_info);
		ERR_FAIL_COND_V_MSG(err, TextureID(),
			vformat("Couldn't create Vulkan image in memory for use with extra GPU memory tracking "
					"(VkResult error %d).",
				err));
	}
	else {
		VkResult err = vkCreateImage(vk_device, &create_info,
			VKC::get_allocation_callbacks(VK_OBJECT_TYPE_IMAGE), &vk_image);
		ERR_FAIL_COND_V_MSG(
			err, TextureID(), vformat("Couldn't create Vulkan image (VkResult error %d).", err));
		err = vmaAllocateMemoryForImage(
			allocator, vk_image, &alloc_create_info, &allocation, &alloc_info);
		ERR_FAIL_COND_V_MSG(err, TextureID(),
			vformat("Couldn't allocate memory for Vulkan image (VkResult error %d).", err));
		err = vmaBindImageMemory2(allocator, allocation, 0, vk_image, nullptr);
		ERR_FAIL_COND_V_MSG(err, TextureID(),
			vformat("Couldn't bind memory to Vulkan image (VkResult error %d).", err));
	}

	// Create view.

	VkImageViewCreateInfo image_view_create_info = {};
	image_view_create_info.sType = VK_STRUCTURE_TYPE_IMAGE_VIEW_CREATE_INFO;
	image_view_create_info.image = vk_image;
	image_view_create_info.viewType = (VkImageViewType)p_format.texture_type;
	image_view_create_info.format = RD_TO_VK_FORMAT[p_view.format];
	image_view_create_info.components.r = (VkComponentSwizzle)p_view.swizzle_r;
	image_view_create_info.components.g = (VkComponentSwizzle)p_view.swizzle_g;
	image_view_create_info.components.b = (VkComponentSwizzle)p_view.swizzle_b;
	image_view_create_info.components.a = (VkComponentSwizzle)p_view.swizzle_a;
	image_view_create_info.subresourceRange.levelCount = create_info.mipLevels;
	image_view_create_info.subresourceRange.layerCount = create_info.arrayLayers;
	if ((p_format.usage_bits & (RDC::TEXTURE_USAGE_DEPTH_STENCIL_ATTACHMENT_BIT |
								   RDC::TEXTURE_USAGE_DEPTH_RESOLVE_ATTACHMENT_BIT))) {
		image_view_create_info.subresourceRange.aspectMask = VK_IMAGE_ASPECT_DEPTH_BIT;
	}
	else {
		image_view_create_info.subresourceRange.aspectMask = VK_IMAGE_ASPECT_COLOR_BIT;
	}

	VkImageViewASTCDecodeModeEXT decode_mode;
	if (enabled_device_extension_names.has(VK_EXT_ASTC_DECODE_MODE_EXTENSION_NAME)) {
		if (image_view_create_info.format >= VK_FORMAT_ASTC_4x4_UNORM_BLOCK &&
			image_view_create_info.format <= VK_FORMAT_ASTC_12x12_SRGB_BLOCK) {
			decode_mode.sType = VK_STRUCTURE_TYPE_IMAGE_VIEW_ASTC_DECODE_MODE_EXT;
			decode_mode.pNext = nullptr;
			decode_mode.decodeMode = VK_FORMAT_R8G8B8A8_UNORM;
			image_view_create_info.pNext = &decode_mode;
		}
	}

	VkImageView vk_image_view = VK_NULL_HANDLE;
	VkResult err = vkCreateImageView(vk_device, &image_view_create_info,
		VKC::get_allocation_callbacks(VK_OBJECT_TYPE_IMAGE_VIEW), &vk_image_view);
	if (err) {
		if (!Engine::is_extra_gpu_memory_tracking_enabled()) {
			vmaDestroyImage(allocator, vk_image, allocation);
		}
		else {
			vkDestroyImage(
				vk_device, vk_image, VKC::get_allocation_callbacks(VK_OBJECT_TYPE_IMAGE));
			vmaFreeMemory(allocator, allocation);
		}

		ERR_FAIL_COND_V_MSG(err, TextureID(),
			vformat("Couldn't create Vulkan image view (VkResult error %d).", err));
	}

	// Bookkeep.

	TextureInfo* tex_info = VersatileResource::allocate<TextureInfo>(resources_allocator);
	tex_info->vk_image = vk_image;
	tex_info->vk_view = vk_image_view;
	tex_info->rd_format = p_format.format;
	tex_info->vk_create_info = create_info;
	tex_info->vk_view_create_info = image_view_create_info;
	tex_info->allocation.handle = allocation;
	tex_info->is_subsampled = Utils::has_flag(create_info.flags, VK_IMAGE_CREATE_SUBSAMPLED_BIT_EXT);
#ifdef DEBUG_ENABLED
	tex_info->transient = Utils::has_flag(p_format.usage_bits, RDC::TEXTURE_USAGE_TRANSIENT_BIT);
#endif
	vmaGetAllocationInfo(allocator, tex_info->allocation.handle, &tex_info->allocation.info);

#if PRINT_NATIVE_COMMANDS
	print_line(
		vformat("vkCreateImageView: 0x%uX for 0x%uX", uint64_t(vk_image_view), uint64_t(vk_image)));
#endif

	return TextureID(tex_info);
}

RDD::TextureID RenderingDeviceDriverVulkan::texture_create_from_extension(uint64_t p_native_texture,
	RDC::TextureType p_type, RDC::DataFormat p_format, uint32_t p_array_layers, bool p_depth_stencil,
	uint32_t p_mipmaps)
{
	VkImage vk_image = (VkImage)p_native_texture;

	// We only need to create a view into the already existing natively-provided texture.

	VkImageViewCreateInfo image_view_create_info = {};
	image_view_create_info.sType = VK_STRUCTURE_TYPE_IMAGE_VIEW_CREATE_INFO;
	image_view_create_info.image = vk_image;
	image_view_create_info.viewType = (VkImageViewType)p_type;
	image_view_create_info.format = RD_TO_VK_FORMAT[p_format];
	image_view_create_info.components.r = VK_COMPONENT_SWIZZLE_R;
	image_view_create_info.components.g = VK_COMPONENT_SWIZZLE_G;
	image_view_create_info.components.b = VK_COMPONENT_SWIZZLE_B;
	image_view_create_info.components.a = VK_COMPONENT_SWIZZLE_A;
	image_view_create_info.subresourceRange.baseMipLevel = 0;
	image_view_create_info.subresourceRange.levelCount = p_mipmaps;
	image_view_create_info.subresourceRange.layerCount = p_array_layers;
	image_view_create_info.subresourceRange.aspectMask =
		p_depth_stencil ? VK_IMAGE_ASPECT_DEPTH_BIT : VK_IMAGE_ASPECT_COLOR_BIT;

	VkImageView vk_image_view = VK_NULL_HANDLE;
	VkResult err = vkCreateImageView(vk_device, &image_view_create_info,
		VKC::get_allocation_callbacks(VK_OBJECT_TYPE_IMAGE_VIEW), &vk_image_view);
	if (err) {
		ERR_FAIL_COND_V_MSG(err, TextureID(),
			vformat("Couldn't create Vulkan image view for extension texture (VkResult error %d).",
				err));
	}

	// Bookkeep.

	TextureInfo* tex_info = VersatileResource::allocate<TextureInfo>(resources_allocator);
	tex_info->vk_view = vk_image_view;
	tex_info->rd_format = p_format;
	tex_info->vk_view_create_info = image_view_create_info;
#ifdef DEBUG_ENABLED
	tex_info->created_from_extension = true;
#endif
	return TextureID(tex_info);
}

RDD::TextureID RenderingDeviceDriverVulkan::texture_create_shared(
	TextureID p_original_texture, const TextureView& p_view)
{
	const TextureInfo* owner_tex_info = (const TextureInfo*)p_original_texture.id;
#ifdef DEBUG_ENABLED
	ERR_FAIL_COND_V(
		!owner_tex_info->allocation.handle && !owner_tex_info->created_from_extension, TextureID());
#endif
	VkImageViewCreateInfo image_view_create_info = owner_tex_info->vk_view_create_info;
	image_view_create_info.format = RD_TO_VK_FORMAT[p_view.format];
	image_view_create_info.components.r = (VkComponentSwizzle)p_view.swizzle_r;
	image_view_create_info.components.g = (VkComponentSwizzle)p_view.swizzle_g;
	image_view_create_info.components.b = (VkComponentSwizzle)p_view.swizzle_b;
	image_view_create_info.components.a = (VkComponentSwizzle)p_view.swizzle_a;

	if (enabled_device_extension_names.has(VK_KHR_MAINTENANCE_2_EXTENSION_NAME)) {
		// May need to make VK_KHR_maintenance2 mandatory and thus has Vulkan 1.1 be our minimum
		// supported version if we require setting this information. Vulkan 1.0 may simply not care.
		if (image_view_create_info.format != owner_tex_info->vk_view_create_info.format) {
			VkImageViewUsageCreateInfo* usage_info = ALLOCA_SINGLE(VkImageViewUsageCreateInfo);
			*usage_info = {};
			usage_info->sType = VK_STRUCTURE_TYPE_IMAGE_VIEW_USAGE_CREATE_INFO;
			usage_info->usage = owner_tex_info->vk_create_info.usage;

			// Certain features may not be available for the format of the view.
			{
				VkFormatProperties properties = {};
				vkGetPhysicalDeviceFormatProperties(
					physical_device, RD_TO_VK_FORMAT[p_view.format], &properties);
				const VkFormatFeatureFlags& supported_flags =
					owner_tex_info->vk_create_info.tiling == VK_IMAGE_TILING_LINEAR
						? properties.linearTilingFeatures
						: properties.optimalTilingFeatures;
				if ((usage_info->usage & VK_IMAGE_USAGE_STORAGE_BIT) &&
					!(supported_flags & VK_FORMAT_FEATURE_STORAGE_IMAGE_BIT)) {
					usage_info->usage = Utils::clear_flag(usage_info->usage, VK_IMAGE_USAGE_STORAGE_BIT);
				}
				if ((usage_info->usage & VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT) &&
					!(supported_flags & VK_FORMAT_FEATURE_COLOR_ATTACHMENT_BIT)) {
					usage_info->usage = Utils::clear_flag(usage_info->usage, VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT);
				}
			}

			image_view_create_info.pNext = usage_info;
		}
	}

	VkImageView new_vk_image_view = VK_NULL_HANDLE;
	VkResult err = vkCreateImageView(vk_device, &image_view_create_info,
		VKC::get_allocation_callbacks(VK_OBJECT_TYPE_IMAGE_VIEW), &new_vk_image_view);
	ERR_FAIL_COND_V_MSG(err, TextureID(),
		vformat("Couldn't create Vulkan image view for shared texture (VkResult error %d).", err));

	// Bookkeep.

	TextureInfo* tex_info = VersatileResource::allocate<TextureInfo>(resources_allocator);
	*tex_info = *owner_tex_info;
	tex_info->vk_view = new_vk_image_view;
	tex_info->vk_view_create_info = image_view_create_info;
	tex_info->allocation = {};

#if PRINT_NATIVE_COMMANDS
	print_line(vformat("vkCreateImageView: 0x%uX for 0x%uX", uint64_t(new_vk_image_view),
		uint64_t(owner_tex_info->vk_view_create_info.image)));
#endif

	return TextureID(tex_info);
}

RDD::TextureID RenderingDeviceDriverVulkan::texture_create_shared_from_slice(
	TextureID p_original_texture, const TextureView& p_view, RDC::TextureSliceType p_slice_type,
	uint32_t p_layer, uint32_t p_layers, uint32_t p_mipmap, uint32_t p_mipmaps)
{
	const TextureInfo* owner_tex_info = (const TextureInfo*)p_original_texture.id;
#ifdef DEBUG_ENABLED
	ERR_FAIL_COND_V(
		!owner_tex_info->allocation.handle && !owner_tex_info->created_from_extension, TextureID());
#endif

	VkImageViewCreateInfo image_view_create_info = owner_tex_info->vk_view_create_info;
	switch (p_slice_type) {
	case RDC::TEXTURE_SLICE_2D: {
		image_view_create_info.viewType = VK_IMAGE_VIEW_TYPE_2D;
	} break;
	case RDC::TEXTURE_SLICE_3D: {
		image_view_create_info.viewType = VK_IMAGE_VIEW_TYPE_3D;
	} break;
	case RDC::TEXTURE_SLICE_CUBEMAP: {
		image_view_create_info.viewType = VK_IMAGE_VIEW_TYPE_CUBE;
	} break;
	case RDC::TEXTURE_SLICE_2D_ARRAY: {
		image_view_create_info.viewType = VK_IMAGE_VIEW_TYPE_2D_ARRAY;
	} break;
	default: {
		return TextureID(nullptr);
	}
	}
	image_view_create_info.format = RD_TO_VK_FORMAT[p_view.format];
	image_view_create_info.components.r = (VkComponentSwizzle)p_view.swizzle_r;
	image_view_create_info.components.g = (VkComponentSwizzle)p_view.swizzle_g;
	image_view_create_info.components.b = (VkComponentSwizzle)p_view.swizzle_b;
	image_view_create_info.components.a = (VkComponentSwizzle)p_view.swizzle_a;
	image_view_create_info.subresourceRange.baseMipLevel = p_mipmap;
	image_view_create_info.subresourceRange.levelCount = p_mipmaps;
	image_view_create_info.subresourceRange.baseArrayLayer = p_layer;
	image_view_create_info.subresourceRange.layerCount = p_layers;

	VkImageView new_vk_image_view = VK_NULL_HANDLE;
	VkResult err = vkCreateImageView(vk_device, &image_view_create_info,
		VKC::get_allocation_callbacks(VK_OBJECT_TYPE_IMAGE_VIEW), &new_vk_image_view);
	ERR_FAIL_COND_V_MSG(err, TextureID(),
		vformat(
			"Couldn't create Vulkan image view for shared texture from slice (VkResult error %d).",
			err));

	// Bookkeep.

	TextureInfo* tex_info = VersatileResource::allocate<TextureInfo>(resources_allocator);
	*tex_info = *owner_tex_info;
	tex_info->vk_view = new_vk_image_view;
	tex_info->vk_view_create_info = image_view_create_info;
	tex_info->allocation = {};

#if PRINT_NATIVE_COMMANDS
	print_line(vformat("vkCreateImageView: 0x%uX for 0x%uX (%d %d %d %d)",
		uint64_t(new_vk_image_view), uint64_t(owner_tex_info->vk_view_create_info.image), p_mipmap,
		p_mipmaps, p_layer, p_layers));
#endif

	return TextureID(tex_info);
}

void RenderingDeviceDriverVulkan::texture_free(TextureID p_texture)
{
	TextureInfo* tex_info = (TextureInfo*)p_texture.id;
	vkDestroyImageView(
		vk_device, tex_info->vk_view, VKC::get_allocation_callbacks(VK_OBJECT_TYPE_IMAGE_VIEW));
	if (tex_info->allocation.handle) {
		if (!Engine::is_extra_gpu_memory_tracking_enabled()) {
			vmaDestroyImage(
				allocator, tex_info->vk_view_create_info.image, tex_info->allocation.handle);
		}
		else {
			vkDestroyImage(vk_device, tex_info->vk_image,
				VKC::get_allocation_callbacks(VK_OBJECT_TYPE_BUFFER));
			vmaFreeMemory(allocator, tex_info->allocation.handle);
		}
	}
	VersatileResource::free(resources_allocator, tex_info);
}

uint64_t RenderingDeviceDriverVulkan::texture_get_allocation_size(TextureID p_texture)
{
	const TextureInfo* tex_info = (const TextureInfo*)p_texture.id;
	return tex_info->allocation.info.size;
}

void RenderingDeviceDriverVulkan::texture_get_copyable_layout(
	TextureID p_texture, const TextureSubresource& p_subresource, TextureCopyableLayout* r_layout)
{
	const TextureInfo* tex_info = (const TextureInfo*)p_texture.id;

	uint32_t w = MAX(1u, tex_info->vk_create_info.extent.width >> p_subresource.mipmap);
	uint32_t h = MAX(1u, tex_info->vk_create_info.extent.height >> p_subresource.mipmap);
	uint32_t d = MAX(1u, tex_info->vk_create_info.extent.depth >> p_subresource.mipmap);

	uint32_t bw = 0, bh = 0;
	RDC::get_compressed_image_format_block_dimensions(tex_info->rd_format, bw, bh);

	uint32_t sbw = 0, sbh = 0;
	*r_layout = {};
	r_layout->size = RDC::get_image_format_required_size(tex_info->rd_format, w, h, d, 1, &sbw, &sbh);
	r_layout->row_pitch = r_layout->size / ((sbh / bh) * d);
}

Vector<uint8_t> RenderingDeviceDriverVulkan::texture_get_data(TextureID p_texture, uint32_t p_layer)
{
	const TextureInfo* tex = (const TextureInfo*)p_texture.id;

	RDC::DataFormat tex_format = tex->rd_format;
	uint32_t tex_width = tex->vk_create_info.extent.width;
	uint32_t tex_height = tex->vk_create_info.extent.height;
	uint32_t tex_depth = tex->vk_create_info.extent.depth;
	uint32_t tex_mipmaps = tex->vk_create_info.mipLevels;

	uint32_t width, height, depth;
	uint32_t tight_mip_size = RDC::get_image_format_required_size(
		tex_format, tex_width, tex_height, tex_depth, tex_mipmaps, &width, &height, &depth);

	Vector<uint8_t> image_data;
	image_data.resize(tight_mip_size);

	uint32_t blockw, blockh;
	RDC::get_compressed_image_format_block_dimensions(tex_format, blockw, blockh);
	uint32_t block_size = RDC::get_compressed_image_format_block_byte_size(tex_format);
	uint32_t pixel_size = RDC::get_image_format_pixel_size(tex_format);

	void* data_ptr = nullptr;
	VkResult err = vmaMapMemory(allocator, tex->allocation.handle, &data_ptr);
	ERR_FAIL_COND_V_MSG(err, Vector<uint8_t>(),
		vformat("Couldn't map Vulkan memory for texture (VkResult error %d).", err));

	{
		uint8_t* w = image_data.ptrw();

		uint32_t mipmap_offset = 0;
		for (uint32_t mm_i = 0; mm_i < tex_mipmaps; mm_i++) {
			uint32_t image_total = RDC::get_image_format_required_size(
				tex_format, tex_width, tex_height, tex_depth, mm_i + 1, &width, &height, &depth);

			uint8_t* write_ptr_mipmap = w + mipmap_offset;
			tight_mip_size = image_total - mipmap_offset;

			VkImageSubresource vk_subres = {};
			vk_subres.aspectMask = VK_IMAGE_ASPECT_COLOR_BIT;
			vk_subres.arrayLayer = p_layer;
			vk_subres.mipLevel = mm_i;

			VkSubresourceLayout vk_layout = {};
			vkGetImageSubresourceLayout(
				vk_device, tex->vk_view_create_info.image, &vk_subres, &vk_layout);

			for (uint32_t z = 0; z < depth; z++) {
				uint8_t* write_ptr = write_ptr_mipmap + z * tight_mip_size / depth;
				const uint8_t* slice_read_ptr =
					(uint8_t*)data_ptr + vk_layout.offset + z * vk_layout.depthPitch;

				if (block_size > 1) {
					// Compressed.
					uint32_t line_width = (block_size * (width / blockw));
					for (uint32_t y = 0; y < height / blockh; y++) {
						const uint8_t* rptr = slice_read_ptr + y * vk_layout.rowPitch;
						uint8_t* wptr = write_ptr + y * line_width;

						memcpy(wptr, rptr, line_width);
					}
				}
				else {
					// Uncompressed.
					for (uint32_t y = 0; y < height; y++) {
						const uint8_t* rptr = slice_read_ptr + y * vk_layout.rowPitch;
						uint8_t* wptr = write_ptr + y * pixel_size * width;
						memcpy(wptr, rptr, (uint64_t)pixel_size * width);
					}
				}
			}

			mipmap_offset = image_total;
		}
	}

	vmaUnmapMemory(allocator, tex->allocation.handle);

	return image_data;
}

uint32_t RenderingDeviceDriverVulkan::texture_get_usages_supported_by_format(
	RDC::DataFormat p_format, bool p_cpu_readable)
{
	if (p_format >= RDC::DATA_FORMAT_ASTC_4x4_SFLOAT_BLOCK &&
		p_format <= RDC::DATA_FORMAT_ASTC_12x12_SFLOAT_BLOCK &&
		!enabled_device_extension_names.has(VK_EXT_TEXTURE_COMPRESSION_ASTC_HDR_EXTENSION_NAME)) {
		// Formats that were introduced later with extensions must not reach
		// vkGetPhysicalDeviceFormatProperties if the extension isn't available. This means it's not
		// supported.
		return 0;
	}
	VkFormatProperties properties = {};
	vkGetPhysicalDeviceFormatProperties(physical_device, RD_TO_VK_FORMAT[p_format], &properties);

	const VkFormatFeatureFlags& flags =
		p_cpu_readable ? properties.linearTilingFeatures : properties.optimalTilingFeatures;

	// Everything supported by default makes an all-or-nothing check easier for the caller.
	uint32_t supported = INT64_MAX;

	if (!(flags & VK_FORMAT_FEATURE_SAMPLED_IMAGE_BIT)) {
		supported = Utils::clear_flag(supported, RDC::TEXTURE_USAGE_SAMPLING_BIT);
	}
	if (!(flags & VK_FORMAT_FEATURE_COLOR_ATTACHMENT_BIT)) {
		supported = Utils::clear_flag(supported, RDC::TEXTURE_USAGE_COLOR_ATTACHMENT_BIT);
	}
	if (!(flags & VK_FORMAT_FEATURE_DEPTH_STENCIL_ATTACHMENT_BIT)) {
		supported = Utils::clear_flag(supported, RDC::TEXTURE_USAGE_DEPTH_STENCIL_ATTACHMENT_BIT);
		supported = Utils::clear_flag(supported, RDC::TEXTURE_USAGE_DEPTH_RESOLVE_ATTACHMENT_BIT);
	}
	if (!(flags & VK_FORMAT_FEATURE_STORAGE_IMAGE_BIT)) {
		supported = Utils::clear_flag(supported, RDC::TEXTURE_USAGE_STORAGE_BIT);
	}
	if (!(flags & VK_FORMAT_FEATURE_STORAGE_IMAGE_ATOMIC_BIT)) {
		supported = Utils::clear_flag(supported, RDC::TEXTURE_USAGE_STORAGE_ATOMIC_BIT);
	}
	if (p_format != RDC::DATA_FORMAT_R8_UINT && p_format != RDC::DATA_FORMAT_R8G8_UNORM) {
		supported = Utils::clear_flag(supported, RDC::TEXTURE_USAGE_VRS_ATTACHMENT_BIT);
	}

	return supported;
}

bool RenderingDeviceDriverVulkan::texture_can_make_shared_with_format(
	TextureID p_texture, RDC::DataFormat p_format, bool& r_raw_reinterpretation)
{
	r_raw_reinterpretation = false;
	return true;
}

