void RasterizerGLES3::begin_frame(double frame_step)
{
	frame++;
	delta = frame_step;

	time_total += frame_step;

	RasterizerCanvasGLES3::set_time(time_total);
	scene->set_time(time_total, frame_step);

	GLES3::Utilities::_capture_timestamps_begin();

	// scene->iteration();
}

